-- Current empty-database schema snapshot for the ZiMu fulfillment service.
-- Generated by concatenating the authoritative Flyway SQL migrations in numeric order.
-- Keep this file structurally equivalent to backend/src/main/resources/db/migration/V1..V53.

-- BEGIN V1__baseline.sql
-- 订单履约中台 V1 PostgreSQL schema
-- Source of truth: wayfinder/tickets/db-schema-design.md (Q1-Q55) and docs/api-contract.md
-- Intended for Flyway V1; Hibernate ddl-auto must be validate, never create/update.

BEGIN;

CREATE SCHEMA app;
CREATE SCHEMA analytics;

CREATE SEQUENCE app.sku_code_seq AS BIGINT MINVALUE 1 MAXVALUE 999999 NO CYCLE;

CREATE TABLE app.outbound_number_counters (
    business_date       DATE PRIMARY KEY,
    last_value          INTEGER NOT NULL CHECK (last_value BETWEEN 1 AND 9999),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE FUNCTION app.next_outbound_order_no(
    generated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
) RETURNS VARCHAR(12)
LANGUAGE plpgsql AS $$
DECLARE
    shanghai_date DATE := (generated_at AT TIME ZONE 'Asia/Shanghai')::DATE;
    allocated_value INTEGER;
BEGIN
    INSERT INTO app.outbound_number_counters (business_date, last_value)
    VALUES (shanghai_date, 1)
    ON CONFLICT (business_date) DO UPDATE
       SET last_value = app.outbound_number_counters.last_value + 1,
           updated_at = CURRENT_TIMESTAMP
       WHERE app.outbound_number_counters.last_value < 9999
    RETURNING last_value INTO allocated_value;

    IF allocated_value IS NULL THEN
        RAISE EXCEPTION 'outbound order number exhausted for business date %', shanghai_date;
    END IF;

    RETURN to_char(shanghai_date, 'YYYYMMDD') || lpad(allocated_value::TEXT, 4, '0');
END;
$$;

-- ---------------------------------------------------------------------------
-- Master data
-- ---------------------------------------------------------------------------

CREATE TABLE app.customers (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_code       VARCHAR(64) NOT NULL UNIQUE,
    customer_name       VARCHAR(200) NOT NULL,
    data_scope          VARCHAR(16) NOT NULL DEFAULT 'BUSINESS'
                        CHECK (data_scope IN ('BUSINESS', 'DEMO')),
    status              VARCHAR(16) NOT NULL DEFAULT 'ACTIVE'
                        CHECK (status IN ('ACTIVE', 'INACTIVE')),
    profile             JSONB NOT NULL DEFAULT '{}'::JSONB
                        CHECK (jsonb_typeof(profile) = 'object'),
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(customer_code) <> ''),
    CHECK (btrim(customer_name) <> '')
);

CREATE TABLE app.customer_source_refs (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id         BIGINT NOT NULL REFERENCES app.customers(id) ON DELETE RESTRICT,
    source_channel      VARCHAR(32) NOT NULL
                        CHECK (source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    source_customer_ref VARCHAR(128) NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (source_channel, source_customer_ref),
    CHECK (btrim(source_customer_ref) <> '')
);

CREATE TABLE app.categories (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_code       VARCHAR(64) NOT NULL UNIQUE,
    category_name       VARCHAR(200) NOT NULL,
    parent_id           BIGINT REFERENCES app.categories(id) ON DELETE RESTRICT,
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(category_code) <> ''),
    CHECK (btrim(category_name) <> ''),
    CHECK (parent_id IS NULL OR parent_id <> id)
);

CREATE TABLE app.products (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_code        VARCHAR(64) NOT NULL UNIQUE,
    product_name        VARCHAR(200) NOT NULL,
    category_id         BIGINT REFERENCES app.categories(id) ON DELETE RESTRICT,
    description         TEXT,
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(product_code) <> ''),
    CHECK (btrim(product_name) <> '')
);

CREATE TABLE app.fulfillment_providers (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provider_code           VARCHAR(32) NOT NULL UNIQUE,
    provider_name           VARCHAR(200) NOT NULL,
    provider_type           VARCHAR(32) NOT NULL
                            CHECK (provider_type IN ('JD_WAREHOUSE', 'THIRD_PARTY')),
    inventory_managed_by_us BOOLEAN NOT NULL DEFAULT FALSE,
    tracking_sla_minutes    INTEGER NOT NULL DEFAULT 1440 CHECK (tracking_sla_minutes > 0),
    active                  BOOLEAN NOT NULL DEFAULT TRUE,
    config                  JSONB NOT NULL DEFAULT '{}'::JSONB
                            CHECK (jsonb_typeof(config) = 'object'),
    lock_version            BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (provider_code ~ '^[A-Z0-9]+$'),
    CHECK (btrim(provider_name) <> '')
);

CREATE TABLE app.skus (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku_sequence_no     BIGINT NOT NULL DEFAULT nextval('app.sku_code_seq') UNIQUE
                        CHECK (sku_sequence_no BETWEEN 1 AND 999999),
    sku_code            VARCHAR(64) NOT NULL UNIQUE,
    product_id          BIGINT NOT NULL REFERENCES app.products(id) ON DELETE RESTRICT,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    specification       VARCHAR(200) NOT NULL,
    unit                VARCHAR(32) NOT NULL,
    barcode             VARCHAR(64),
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (sku_code ~ '^SKU-[A-Z0-9]+-[0-9]{6}$'),
    CHECK (btrim(specification) <> ''),
    CHECK (btrim(unit) <> ''),
    CHECK (barcode IS NULL OR btrim(barcode) <> '')
);

CREATE TABLE app.sku_aliases (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    alias_type          VARCHAR(32) NOT NULL
                        CHECK (alias_type IN ('NAME', 'BARCODE', 'SPECIFICATION', 'OTHER')),
    alias_value         VARCHAR(255) NOT NULL,
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (sku_id, alias_type, alias_value),
    CHECK (btrim(alias_value) <> '')
);

CREATE TABLE app.source_channel_skus (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_channel      VARCHAR(32) NOT NULL
                        CHECK (source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    source_sku_ref      VARCHAR(128) NOT NULL,
    source_product_name VARCHAR(255),
    source_specification VARCHAR(255),
    quantity_multiplier NUMERIC(18,3) CHECK (quantity_multiplier > 0),
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (source_channel, source_sku_ref),
    CHECK (btrim(source_sku_ref) <> '')
);

CREATE TABLE app.provider_skus (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    provider_sku_code   VARCHAR(128) NOT NULL,
    merchant_sku_code   VARCHAR(128),
    external_codes      JSONB NOT NULL DEFAULT '{}'::JSONB
                        CHECK (jsonb_typeof(external_codes) = 'object'),
    active              BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (fulfillment_provider_id, provider_sku_code),
    UNIQUE (fulfillment_provider_id, sku_id),
    CHECK (btrim(provider_sku_code) <> '')
);

CREATE TABLE app.provider_stock_snapshots (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    warehouse_code      VARCHAR(128) NOT NULL,
    stock_num           NUMERIC(18,3) NOT NULL CHECK (stock_num >= 0),
    usable_num          NUMERIC(18,3) NOT NULL CHECK (usable_num >= 0 AND usable_num <= stock_num),
    synced_at           TIMESTAMPTZ NOT NULL,
    source_ref          VARCHAR(255),
    raw_payload         JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(warehouse_code) <> '')
);

-- ---------------------------------------------------------------------------
-- File intake and canonical orders
-- ---------------------------------------------------------------------------

CREATE TABLE app.import_batches (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_no            VARCHAR(64) NOT NULL UNIQUE,
    batch_type          VARCHAR(32) NOT NULL
                        CHECK (batch_type IN ('SOURCE_ORDER', 'PROVIDER_TRACKING')),
    import_mode         VARCHAR(16) NOT NULL DEFAULT 'NEW'
                        CHECK (import_mode IN ('NEW', 'REVISION')),
    parent_import_batch_id BIGINT REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    revision_no         INTEGER NOT NULL DEFAULT 1 CHECK (revision_no > 0),
    source_channel      VARCHAR(32)
                        CHECK (source_channel IS NULL OR source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    fulfillment_provider_id BIGINT REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    source_fulfillment_export_id BIGINT,
    template_family     VARCHAR(128) NOT NULL,
    template_version    VARCHAR(64) NOT NULL,
    template_fingerprint VARCHAR(128) NOT NULL,
    original_file_name VARCHAR(255) NOT NULL,
    content_sha256      CHAR(64) NOT NULL,
    file_ref            TEXT NOT NULL,
    status              VARCHAR(32) NOT NULL DEFAULT 'RECEIVED'
                        CHECK (status IN ('RECEIVED', 'PROCESSING', 'COMPLETED', 'COMPLETED_WITH_REVIEW', 'FAILED')),
    error_detail        JSONB,
    uploaded_by         VARCHAR(128) NOT NULL,
    received_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
    CHECK (
        (batch_type = 'SOURCE_ORDER' AND source_channel IS NOT NULL
            AND fulfillment_provider_id IS NULL AND source_fulfillment_export_id IS NULL)
        OR
        (batch_type = 'PROVIDER_TRACKING' AND source_channel IS NULL
            AND fulfillment_provider_id IS NOT NULL AND source_fulfillment_export_id IS NOT NULL)
    ),
    CHECK (
        (import_mode = 'NEW' AND parent_import_batch_id IS NULL AND revision_no = 1)
        OR
        (import_mode = 'REVISION' AND parent_import_batch_id IS NOT NULL AND revision_no > 1)
    ),
    CHECK (parent_import_batch_id IS NULL OR parent_import_batch_id <> id),
    CHECK (btrim(batch_no) <> ''),
    CHECK (btrim(template_family) <> ''),
    CHECK (btrim(template_version) <> ''),
    CHECK (btrim(template_fingerprint) <> ''),
    CHECK (btrim(original_file_name) <> ''),
    CHECK (btrim(file_ref) <> ''),
    CHECK (btrim(uploaded_by) <> '')
);

CREATE TABLE app.orders (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_no            VARCHAR(64) NOT NULL UNIQUE,
    data_scope          VARCHAR(16) NOT NULL DEFAULT 'BUSINESS'
                        CHECK (data_scope IN ('BUSINESS', 'DEMO')),
    source_channel      VARCHAR(32) NOT NULL
                        CHECK (source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    source_ref          VARCHAR(128) NOT NULL,
    source_ref_kind     VARCHAR(16) NOT NULL
                        CHECK (source_ref_kind IN ('PROVIDED', 'SYNTHETIC')),
    source_version      VARCHAR(64),
    source_import_batch_id BIGINT REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    customer_id         BIGINT REFERENCES app.customers(id) ON DELETE RESTRICT,
    correction_of_order_id BIGINT REFERENCES app.orders(id) ON DELETE RESTRICT,
    order_status        VARCHAR(32) NOT NULL DEFAULT 'RECEIVED'
                        CHECK (order_status IN (
                            'RECEIVED', 'VALIDATED', 'SKU_MAPPED', 'FULFILLING', 'SHIPPED', 'SYNCED', 'CLOSED',
                            'NEED_REVIEW', 'OUT_OF_STOCK', 'PROCUREMENT_PENDING', 'FULFILLMENT_EXCEPTION',
                            'SYNC_FAILED', 'CANCELLED'
                        )),
    settlement_method   VARCHAR(32) NOT NULL
                        CHECK (settlement_method IN ('MONTHLY', 'IMMEDIATE', 'CREDIT_TERM', 'PREPAID', 'COD', 'OTHER')),
    settlement_time     TIMESTAMPTZ NOT NULL,
    receiver_name       VARCHAR(200) NOT NULL,
    receiver_phone      VARCHAR(64) NOT NULL,
    receiver_address    TEXT NOT NULL,
    remark              TEXT,
    evidence_refs       JSONB NOT NULL DEFAULT '[]'::JSONB
                        CHECK (jsonb_typeof(evidence_refs) = 'array'),
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (source_channel, source_ref),
    CHECK (btrim(order_no) <> ''),
    CHECK (btrim(source_ref) <> ''),
    CHECK (btrim(receiver_name) <> ''),
    CHECK (btrim(receiver_phone) <> ''),
    CHECK (btrim(receiver_address) <> ''),
    CHECK (correction_of_order_id IS NULL OR correction_of_order_id <> id),
    CHECK (
        customer_id IS NOT NULL
        OR order_status IN ('RECEIVED', 'NEED_REVIEW', 'CANCELLED')
    ),
    CHECK (data_scope = 'DEMO' OR source_channel = 'WECOM' OR source_import_batch_id IS NOT NULL),
    CHECK (data_scope = 'DEMO' OR source_channel <> 'WECOM' OR source_import_batch_id IS NULL)
);

CREATE TABLE app.order_lines (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id            BIGINT NOT NULL REFERENCES app.orders(id) ON DELETE RESTRICT,
    line_no             INTEGER NOT NULL CHECK (line_no > 0),
    line_type           VARCHAR(32) NOT NULL
                        CHECK (line_type IN ('SINGLE', 'CUSTOM_BUNDLE')),
    sku_id              BIGINT REFERENCES app.skus(id) ON DELETE RESTRICT,
    fulfillment_provider_id BIGINT REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    product_name_snapshot VARCHAR(255) NOT NULL,
    sku_code_snapshot   VARCHAR(64),
    specification_snapshot VARCHAR(255) NOT NULL,
    unit_snapshot       VARCHAR(32) NOT NULL,
    source_quantity_snapshot NUMERIC(18,3) CHECK (source_quantity_snapshot > 0),
    mapping_multiplier_snapshot NUMERIC(18,3) CHECK (mapping_multiplier_snapshot > 0),
    requested_quantity NUMERIC(18,3) NOT NULL CHECK (requested_quantity > 0),
    processing_stage    VARCHAR(32) NOT NULL DEFAULT 'NEED_REVIEW'
                        CHECK (processing_stage IN (
                            'NEED_REVIEW', 'READY_TO_EXPORT', 'WAITING_PROVIDER', 'PROCUREMENT_IN_PROGRESS',
                            'TRACKING_RECEIVED', 'RETURN_FILE_READY', 'COMPLETED', 'EXCEPTION'
                        )),
    fulfillment_committed_at TIMESTAMPTZ,
    exception_code      VARCHAR(64),
    exception_reason    TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (order_id, line_no),
    CHECK (btrim(product_name_snapshot) <> ''),
    CHECK (btrim(specification_snapshot) <> ''),
    CHECK (btrim(unit_snapshot) <> ''),
    CHECK (line_type <> 'CUSTOM_BUNDLE' OR trunc(requested_quantity) = requested_quantity),
    CHECK (line_type <> 'CUSTOM_BUNDLE' OR sku_id IS NULL),
    CHECK (
        (source_quantity_snapshot IS NULL AND mapping_multiplier_snapshot IS NULL)
        OR (source_quantity_snapshot IS NOT NULL AND mapping_multiplier_snapshot IS NOT NULL)
    ),
    CHECK (
        line_type <> 'SINGLE'
        OR source_quantity_snapshot IS NULL
        OR requested_quantity = source_quantity_snapshot * mapping_multiplier_snapshot
    ),
    CHECK ((exception_code IS NULL) = (exception_reason IS NULL))
);

CREATE TABLE app.order_line_components (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_line_id       BIGINT NOT NULL REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    component_no        INTEGER NOT NULL CHECK (component_no > 0),
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    quantity_per_bundle NUMERIC(18,3) NOT NULL CHECK (quantity_per_bundle > 0),
    total_quantity      NUMERIC(18,3) NOT NULL CHECK (total_quantity > 0),
    product_name_snapshot VARCHAR(255) NOT NULL,
    specification_snapshot VARCHAR(255) NOT NULL,
    unit_snapshot       VARCHAR(32) NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (order_line_id, component_no),
    UNIQUE (order_line_id, sku_id),
    CHECK (btrim(product_name_snapshot) <> ''),
    CHECK (btrim(specification_snapshot) <> ''),
    CHECK (btrim(unit_snapshot) <> '')
);

CREATE TABLE app.raw_import_rows (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    import_batch_id     BIGINT NOT NULL REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    sheet_name          VARCHAR(255) NOT NULL,
    sheet_index         INTEGER NOT NULL CHECK (sheet_index >= 0),
    row_index           INTEGER NOT NULL CHECK (row_index > 0),
    raw_cells           JSONB NOT NULL CHECK (jsonb_typeof(raw_cells) IN ('object', 'array')),
    source_order_ref    VARCHAR(128),
    status              VARCHAR(32) NOT NULL DEFAULT 'RECEIVED'
                        CHECK (status IN ('RECEIVED', 'ACCEPTED', 'NEED_REVIEW', 'REJECTED')),
    error_code          VARCHAR(64),
    error_detail        JSONB,
    order_id            BIGINT REFERENCES app.orders(id) ON DELETE RESTRICT,
    order_line_id       BIGINT REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (import_batch_id, sheet_index, row_index),
    CHECK (btrim(sheet_name) <> ''),
    CHECK ((status IN ('NEED_REVIEW', 'REJECTED')) OR error_code IS NULL)
);

CREATE TABLE app.order_versions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id            BIGINT NOT NULL REFERENCES app.orders(id) ON DELETE RESTRICT,
    version_no          BIGINT NOT NULL CHECK (version_no > 0),
    source_version      VARCHAR(64),
    change_reason       VARCHAR(255) NOT NULL,
    triggered_by        VARCHAR(128) NOT NULL,
    snapshot            JSONB NOT NULL CHECK (jsonb_typeof(snapshot) = 'object'),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (order_id, version_no),
    CHECK (btrim(change_reason) <> ''),
    CHECK (btrim(triggered_by) <> '')
);

-- ---------------------------------------------------------------------------
-- Fulfillment, shipment and procurement
-- ---------------------------------------------------------------------------

CREATE TABLE app.fulfillments (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fulfillment_no      VARCHAR(64) NOT NULL UNIQUE,
    order_line_id       BIGINT NOT NULL UNIQUE REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    requested_quantity NUMERIC(18,3) NOT NULL CHECK (requested_quantity > 0),
    cumulative_shipped_quantity NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK (cumulative_shipped_quantity >= 0),
    cancelled_quantity NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK (cancelled_quantity >= 0),
    shipping_progress   VARCHAR(32) NOT NULL DEFAULT 'NOT_SHIPPED'
                        CHECK (shipping_progress IN ('NOT_SHIPPED', 'PARTIALLY_SHIPPED', 'SHIPPED')),
    outcome             VARCHAR(32) NOT NULL DEFAULT 'IN_PROGRESS'
                        CHECK (outcome IN ('IN_PROGRESS', 'FULLY_FULFILLED', 'PARTIALLY_FULFILLED', 'CANCELLED')),
    exception_code      VARCHAR(64),
    exception_reason    TEXT,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(fulfillment_no) <> ''),
    CHECK (cumulative_shipped_quantity + cancelled_quantity <= requested_quantity),
    CHECK (
        (shipping_progress = 'NOT_SHIPPED' AND cumulative_shipped_quantity = 0)
        OR (shipping_progress = 'PARTIALLY_SHIPPED' AND cumulative_shipped_quantity > 0 AND cumulative_shipped_quantity < requested_quantity)
        OR (shipping_progress = 'SHIPPED' AND cumulative_shipped_quantity = requested_quantity)
    ),
    CHECK (
        outcome = 'IN_PROGRESS'
        OR (outcome = 'FULLY_FULFILLED' AND cumulative_shipped_quantity = requested_quantity AND cancelled_quantity = 0)
        OR (outcome = 'PARTIALLY_FULFILLED' AND cumulative_shipped_quantity > 0 AND cancelled_quantity > 0
            AND cumulative_shipped_quantity + cancelled_quantity = requested_quantity)
        OR (outcome = 'CANCELLED' AND cumulative_shipped_quantity = 0 AND cancelled_quantity = requested_quantity)
    ),
    CHECK ((exception_code IS NULL) = (exception_reason IS NULL))
);

CREATE TABLE app.shipments (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shipment_no         VARCHAR(64) NOT NULL UNIQUE,
    order_id            BIGINT NOT NULL REFERENCES app.orders(id) ON DELETE RESTRICT,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    outbound_order_no   VARCHAR(12) NOT NULL DEFAULT app.next_outbound_order_no(),
    shipment_sequence   INTEGER NOT NULL CHECK (shipment_sequence > 0),
    receiver_name_snapshot VARCHAR(200) NOT NULL,
    receiver_phone_snapshot VARCHAR(64) NOT NULL,
    receiver_address_snapshot TEXT NOT NULL,
    shipment_status     VARCHAR(32) NOT NULL DEFAULT 'CREATED'
                        CHECK (shipment_status IN ('CREATED', 'SHIPPED', 'FAILED', 'DELIVERED')),
    failure_reason      TEXT,
    shipped_at          TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (fulfillment_provider_id, outbound_order_no),
    UNIQUE (order_id, fulfillment_provider_id, shipment_sequence),
    CHECK (btrim(shipment_no) <> ''),
    CHECK (outbound_order_no ~ '^[0-9]{12}$'),
    CHECK (btrim(receiver_name_snapshot) <> ''),
    CHECK (btrim(receiver_phone_snapshot) <> ''),
    CHECK (btrim(receiver_address_snapshot) <> ''),
    CHECK ((shipment_status IN ('SHIPPED', 'DELIVERED')) = (shipped_at IS NOT NULL)),
    CHECK ((shipment_status = 'FAILED') = (failure_reason IS NOT NULL))
);

CREATE TABLE app.shipment_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shipment_id         BIGINT NOT NULL REFERENCES app.shipments(id) ON DELETE RESTRICT,
    fulfillment_id      BIGINT NOT NULL REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    instructed_quantity NUMERIC(18,3) NOT NULL CHECK (instructed_quantity > 0),
    shipped_quantity    NUMERIC(18,3) CHECK (shipped_quantity >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (shipment_id, fulfillment_id),
    CHECK (shipped_quantity IS NULL OR shipped_quantity <= instructed_quantity)
);

CREATE TABLE app.trackings (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shipment_id         BIGINT NOT NULL UNIQUE REFERENCES app.shipments(id) ON DELETE RESTRICT,
    logistics_company_code VARCHAR(64) NOT NULL,
    logistics_company_name VARCHAR(128) NOT NULL,
    tracking_number     VARCHAR(128) NOT NULL,
    provider_tracking_batch_id BIGINT REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    received_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    raw_payload         JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (logistics_company_code, tracking_number),
    CHECK (btrim(logistics_company_code) <> ''),
    CHECK (btrim(logistics_company_name) <> ''),
    CHECK (btrim(tracking_number) <> '')
);

CREATE TABLE app.shipment_syncs (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shipment_id         BIGINT NOT NULL REFERENCES app.shipments(id) ON DELETE RESTRICT,
    source_channel      VARCHAR(32) NOT NULL
                        CHECK (source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    sync_status         VARCHAR(32) NOT NULL DEFAULT 'PENDING'
                        CHECK (sync_status IN ('PENDING', 'SYNCED', 'SYNC_FAILED')),
    attempt_count       INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    last_error_code     VARCHAR(64),
    last_error_message  TEXT,
    synced_at           TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (shipment_id, source_channel),
    CHECK ((sync_status = 'SYNCED') = (synced_at IS NOT NULL)),
    CHECK ((last_error_code IS NULL) = (last_error_message IS NULL))
);

CREATE TABLE app.procurement_tickets (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ticket_no           VARCHAR(64) NOT NULL UNIQUE,
    fulfillment_id      BIGINT NOT NULL REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    retry_of_ticket_id  BIGINT REFERENCES app.procurement_tickets(id) ON DELETE RESTRICT,
    procurement_status  VARCHAR(32) NOT NULL DEFAULT 'PENDING'
                        CHECK (procurement_status IN ('PENDING', 'SUCCESS', 'PARTIAL', 'FAILED', 'CANCELLED')),
    priority            VARCHAR(16) NOT NULL DEFAULT 'NORMAL'
                        CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
    delivery_address    TEXT NOT NULL,
    required_delivery_time TIMESTAMPTZ,
    remark              TEXT,
    created_by          VARCHAR(128) NOT NULL,
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(ticket_no) <> ''),
    CHECK (btrim(delivery_address) <> ''),
    CHECK (btrim(created_by) <> ''),
    CHECK (retry_of_ticket_id IS NULL OR retry_of_ticket_id <> id)
);

CREATE TABLE app.procurement_ticket_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    procurement_ticket_id BIGINT NOT NULL REFERENCES app.procurement_tickets(id) ON DELETE RESTRICT,
    sku_id              BIGINT NOT NULL REFERENCES app.skus(id) ON DELETE RESTRICT,
    order_line_component_id BIGINT REFERENCES app.order_line_components(id) ON DELETE RESTRICT,
    requested_quantity NUMERIC(18,3) NOT NULL CHECK (requested_quantity > 0),
    fulfilled_quantity NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK (fulfilled_quantity >= 0),
    remaining_quantity NUMERIC(18,3) GENERATED ALWAYS AS (requested_quantity - fulfilled_quantity) STORED,
    unit_snapshot       VARCHAR(32) NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE NULLS NOT DISTINCT (procurement_ticket_id, sku_id, order_line_component_id),
    CHECK (fulfilled_quantity <= requested_quantity),
    CHECK (btrim(unit_snapshot) <> '')
);

CREATE TABLE app.procurement_receipts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    receipt_no          VARCHAR(64) NOT NULL UNIQUE,
    procurement_ticket_id BIGINT NOT NULL REFERENCES app.procurement_tickets(id) ON DELETE RESTRICT,
    result              VARCHAR(16) NOT NULL CHECK (result IN ('SUCCESS', 'PARTIAL', 'FAILED')),
    expected_ship_time  TIMESTAMPTZ,
    source_ref          VARCHAR(255),
    remark              TEXT,
    received_by         VARCHAR(128) NOT NULL,
    received_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(receipt_no) <> ''),
    CHECK (btrim(received_by) <> '')
);

CREATE TABLE app.procurement_receipt_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    procurement_receipt_id BIGINT NOT NULL REFERENCES app.procurement_receipts(id) ON DELETE RESTRICT,
    procurement_ticket_item_id BIGINT NOT NULL REFERENCES app.procurement_ticket_items(id) ON DELETE RESTRICT,
    available_quantity NUMERIC(18,3) NOT NULL CHECK (available_quantity >= 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (procurement_receipt_id, procurement_ticket_item_id)
);

-- ---------------------------------------------------------------------------
-- Fulfillment exports and source-format return files
-- ---------------------------------------------------------------------------

CREATE TABLE app.fulfillment_exports (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    export_batch_no     VARCHAR(64) NOT NULL UNIQUE,
    fulfillment_provider_id BIGINT NOT NULL REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    export_kind         VARCHAR(32) NOT NULL CHECK (export_kind IN ('JD_WAREHOUSE', 'THIRD_PARTY')),
    template_version    VARCHAR(64) NOT NULL,
    file_ref            TEXT NOT NULL,
    file_sha256         CHAR(64) NOT NULL,
    tracking_due_at     TIMESTAMPTZ NOT NULL,
    generated_by        VARCHAR(128) NOT NULL,
    generated_at        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(export_batch_no) <> ''),
    CHECK (btrim(template_version) <> ''),
    CHECK (btrim(file_ref) <> ''),
    CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
    CHECK (btrim(generated_by) <> ''),
    CHECK (tracking_due_at >= generated_at)
);

ALTER TABLE app.import_batches
ADD CONSTRAINT fk_import_batches_source_fulfillment_export
FOREIGN KEY (source_fulfillment_export_id)
REFERENCES app.fulfillment_exports(id) ON DELETE RESTRICT;

CREATE TABLE app.fulfillment_export_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fulfillment_export_id BIGINT NOT NULL REFERENCES app.fulfillment_exports(id) ON DELETE RESTRICT,
    export_line_no      INTEGER NOT NULL CHECK (export_line_no > 0),
    shipment_id         BIGINT NOT NULL REFERENCES app.shipments(id) ON DELETE RESTRICT,
    fulfillment_id      BIGINT NOT NULL REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    order_line_id       BIGINT NOT NULL REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    order_line_component_id BIGINT REFERENCES app.order_line_components(id) ON DELETE RESTRICT,
    raw_import_row_id   BIGINT REFERENCES app.raw_import_rows(id) ON DELETE RESTRICT,
    outbound_order_no   VARCHAR(12) NOT NULL,
    provider_sku_code   VARCHAR(128) NOT NULL,
    instructed_quantity NUMERIC(18,3) NOT NULL CHECK (instructed_quantity > 0),
    unit_snapshot       VARCHAR(32) NOT NULL,
    item_amount         NUMERIC(18,2),
    stock_snapshot_ids  JSONB NOT NULL DEFAULT '[]'::JSONB
                        CHECK (jsonb_typeof(stock_snapshot_ids) = 'array'),
    output_cells        JSONB NOT NULL CHECK (jsonb_typeof(output_cells) IN ('object', 'array')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (fulfillment_export_id, export_line_no),
    UNIQUE NULLS NOT DISTINCT (
        fulfillment_export_id,
        shipment_id,
        fulfillment_id,
        order_line_component_id
    ),
    CHECK (outbound_order_no ~ '^[0-9]{12}$'),
    CHECK (btrim(provider_sku_code) <> ''),
    CHECK (btrim(unit_snapshot) <> ''),
    CHECK (item_amount IS NULL OR item_amount = 0)
);

CREATE TABLE app.source_return_exports (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    import_batch_id     BIGINT NOT NULL REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    version_no          INTEGER NOT NULL CHECK (version_no > 0),
    is_final            BOOLEAN NOT NULL DEFAULT FALSE,
    template_version    VARCHAR(64) NOT NULL,
    tracking_cutoff_at  TIMESTAMPTZ NOT NULL,
    file_ref            TEXT NOT NULL,
    file_sha256         CHAR(64) NOT NULL,
    generated_by        VARCHAR(128) NOT NULL,
    generated_at        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (import_batch_id, version_no),
    CHECK (btrim(template_version) <> ''),
    CHECK (btrim(file_ref) <> ''),
    CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
    CHECK (btrim(generated_by) <> '')
);

CREATE TABLE app.source_return_export_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_return_export_id BIGINT NOT NULL REFERENCES app.source_return_exports(id) ON DELETE RESTRICT,
    raw_import_row_id   BIGINT NOT NULL REFERENCES app.raw_import_rows(id) ON DELETE RESTRICT,
    order_line_id       BIGINT REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    shipment_id         BIGINT REFERENCES app.shipments(id) ON DELETE RESTRICT,
    shipment_sequence   INTEGER CHECK (shipment_sequence IS NULL OR shipment_sequence > 0),
    item_result         VARCHAR(16) NOT NULL CHECK (item_result IN ('FILLED', 'PENDING', 'CANCELLED', 'EXCEPTION')),
    output_sheet_name   VARCHAR(255) NOT NULL,
    output_row_index    INTEGER NOT NULL CHECK (output_row_index > 0),
    shipped_quantity    NUMERIC(18,3) CHECK (shipped_quantity > 0),
    logistics_company  VARCHAR(128),
    tracking_number     VARCHAR(128),
    fulfillment_outcome VARCHAR(32)
                        CHECK (fulfillment_outcome IS NULL OR fulfillment_outcome IN (
                            'IN_PROGRESS', 'FULLY_FULFILLED', 'PARTIALLY_FULFILLED', 'CANCELLED'
                        )),
    cancelled_quantity NUMERIC(18,3) CHECK (cancelled_quantity IS NULL OR cancelled_quantity >= 0),
    exception_reason   TEXT,
    output_cells       JSONB NOT NULL CHECK (jsonb_typeof(output_cells) IN ('object', 'array')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(output_sheet_name) <> ''),
    CHECK (
        (item_result = 'FILLED' AND shipment_id IS NOT NULL AND shipped_quantity IS NOT NULL
            AND shipment_sequence IS NOT NULL AND logistics_company IS NOT NULL AND tracking_number IS NOT NULL)
        OR (item_result = 'PENDING' AND shipment_id IS NULL AND shipped_quantity IS NULL
            AND shipment_sequence IS NULL AND logistics_company IS NULL AND tracking_number IS NULL)
        OR (item_result = 'CANCELLED' AND order_line_id IS NOT NULL AND shipment_id IS NULL
            AND shipped_quantity IS NULL AND shipment_sequence IS NULL
            AND logistics_company IS NULL AND tracking_number IS NULL
            AND fulfillment_outcome = 'CANCELLED' AND cancelled_quantity > 0)
        OR (item_result = 'EXCEPTION' AND exception_reason IS NOT NULL)
    )
);

