CREATE TABLE app.review_cases (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_no             VARCHAR(64) NOT NULL UNIQUE,
    case_type           VARCHAR(64) NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'OPEN'
                        CHECK (status IN ('OPEN', 'RESOLVED', 'DISMISSED')),
    responsible_team    VARCHAR(128) NOT NULL,
    reason_code         VARCHAR(64) NOT NULL,
    order_id            BIGINT REFERENCES app.orders(id) ON DELETE RESTRICT,
    order_line_id       BIGINT REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    fulfillment_id      BIGINT REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    shipment_id         BIGINT REFERENCES app.shipments(id) ON DELETE RESTRICT,
    import_batch_id     BIGINT REFERENCES app.import_batches(id) ON DELETE RESTRICT,
    raw_import_row_id   BIGINT REFERENCES app.raw_import_rows(id) ON DELETE RESTRICT,
    detail              JSONB NOT NULL DEFAULT '{}'::JSONB CHECK (jsonb_typeof(detail) = 'object'),
    resolution          JSONB,
    resolution_version  BIGINT NOT NULL DEFAULT 0 CHECK (resolution_version >= 0),
    resolved_by         VARCHAR(128),
    resolved_at         TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(case_no) <> ''),
    CHECK (btrim(case_type) <> ''),
    CHECK (btrim(responsible_team) <> ''),
    CHECK (btrim(reason_code) <> ''),
    CHECK (num_nonnulls(order_id, order_line_id, fulfillment_id, shipment_id, import_batch_id, raw_import_row_id) > 0),
    CHECK (
        (status = 'OPEN' AND resolved_by IS NULL AND resolved_at IS NULL)
        OR (status IN ('RESOLVED', 'DISMISSED') AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL)
    )
);

CREATE TABLE app.operational_alerts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alert_no            VARCHAR(64) NOT NULL UNIQUE,
    alert_type          VARCHAR(64) NOT NULL,
    severity            VARCHAR(16) NOT NULL CHECK (severity IN ('YELLOW', 'RED')),
    status              VARCHAR(16) NOT NULL DEFAULT 'OPEN'
                        CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED')),
    order_id            BIGINT REFERENCES app.orders(id) ON DELETE RESTRICT,
    order_line_id       BIGINT REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    fulfillment_id      BIGINT REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    shipment_id         BIGINT REFERENCES app.shipments(id) ON DELETE RESTRICT,
    message             TEXT NOT NULL,
    detail              JSONB NOT NULL DEFAULT '{}'::JSONB CHECK (jsonb_typeof(detail) = 'object'),
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    acknowledged_by     VARCHAR(128),
    acknowledged_at     TIMESTAMPTZ,
    resolved_at         TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(alert_no) <> ''),
    CHECK (btrim(alert_type) <> ''),
    CHECK (btrim(message) <> ''),
    CHECK (num_nonnulls(order_id, order_line_id, fulfillment_id, shipment_id) > 0),
    CHECK (
        (status = 'OPEN' AND acknowledged_by IS NULL AND acknowledged_at IS NULL AND resolved_at IS NULL)
        OR (status = 'ACKNOWLEDGED' AND acknowledged_by IS NOT NULL AND acknowledged_at IS NOT NULL AND resolved_at IS NULL)
        OR (status = 'RESOLVED' AND resolved_at IS NOT NULL)
    )
);

CREATE TABLE app.connector_configs (
    source_channel      VARCHAR(32) PRIMARY KEY
                        CHECK (source_channel IN ('CAISHIXIAN', 'JUFUBAO', 'FEIXIANG', 'WECOM')),
    enabled             BOOLEAN NOT NULL DEFAULT TRUE,
    mode                VARCHAR(16) NOT NULL DEFAULT 'MOCK' CHECK (mode IN ('MOCK', 'REAL')),
    transport_mode      VARCHAR(16) NOT NULL DEFAULT 'EXCEL' CHECK (transport_mode IN ('EXCEL', 'API')),
    lock_version        BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    last_pull_at        TIMESTAMPTZ,
    last_error          JSONB,
    config              JSONB NOT NULL DEFAULT '{}'::JSONB CHECK (jsonb_typeof(config) = 'object'),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

