DO $$
DECLARE
    table_name TEXT;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'customers', 'customer_source_refs', 'categories', 'products', 'fulfillment_providers',
        'skus', 'source_channel_skus', 'provider_skus', 'orders', 'order_lines', 'raw_import_rows',
        'fulfillments', 'shipments', 'shipment_items', 'shipment_syncs', 'procurement_tickets',
        'procurement_ticket_items', 'review_cases', 'operational_alerts', 'connector_configs',
        'idempotency_registry', 'order_event_types'
    ]
    LOOP
        EXECUTE format(
            'CREATE TRIGGER %I BEFORE UPDATE ON app.%I FOR EACH ROW EXECUTE FUNCTION app.set_updated_at()',
            'trg_' || table_name || '_updated_at', table_name
        );
    END LOOP;
END;
$$;

