-- ---------------------------------------------------------------------------
-- Operational progress projection
-- ---------------------------------------------------------------------------

CREATE VIEW app.v_order_progress_summary AS
WITH line_rollup AS (
    SELECT
        o.id AS order_id,
        count(ol.id)::INTEGER AS total_count,
        count(*) FILTER (WHERE ol.processing_stage = 'COMPLETED')::INTEGER AS completed_count,
        bool_or(ol.processing_stage = 'EXCEPTION') AS has_exception,
        bool_or(ol.processing_stage IN ('NEED_REVIEW', 'WAITING_PROVIDER', 'PROCUREMENT_IN_PROGRESS')) AS has_waiting,
        min(
            CASE ol.processing_stage
                WHEN 'NEED_REVIEW' THEN 10
                WHEN 'READY_TO_EXPORT' THEN 20
                WHEN 'PROCUREMENT_IN_PROGRESS' THEN 25
                WHEN 'WAITING_PROVIDER' THEN 30
                WHEN 'TRACKING_RECEIVED' THEN 40
                WHEN 'RETURN_FILE_READY' THEN 50
                WHEN 'COMPLETED' THEN 60
                WHEN 'EXCEPTION' THEN 100
            END
        ) FILTER (WHERE ol.processing_stage <> 'EXCEPTION') AS minimum_progress_rank,
        min(ol.exception_reason) FILTER (WHERE ol.processing_stage = 'EXCEPTION') AS line_exception_reason
    FROM app.orders o
    JOIN app.order_lines ol ON ol.order_id = o.id
    WHERE o.data_scope = 'BUSINESS'
    GROUP BY o.id
), alert_rollup AS (
    SELECT
        order_id,
        bool_or(severity = 'RED') AS has_red_alert,
        bool_or(severity = 'YELLOW') AS has_yellow_alert,
        min(message) AS first_alert_message
    FROM app.operational_alerts
    WHERE status IN ('OPEN', 'ACKNOWLEDGED')
    GROUP BY order_id
)
SELECT
    lr.order_id,
    CASE
        WHEN lr.has_exception THEN 'EXCEPTION'
        WHEN lr.completed_count = lr.total_count THEN 'COMPLETED'
        WHEN lr.minimum_progress_rank = 10 THEN 'NEED_REVIEW'
        WHEN lr.minimum_progress_rank = 20 THEN 'READY_TO_EXPORT'
        WHEN lr.minimum_progress_rank = 25 THEN 'PROCUREMENT_IN_PROGRESS'
        WHEN lr.minimum_progress_rank = 30 THEN 'WAITING_PROVIDER'
        WHEN lr.minimum_progress_rank = 40 THEN 'TRACKING_RECEIVED'
        WHEN lr.minimum_progress_rank = 50 THEN 'RETURN_FILE_READY'
        ELSE 'COMPLETED'
    END AS processing_stage,
    CASE
        WHEN lr.has_exception OR COALESCE(ar.has_red_alert, FALSE) THEN 'RED'
        WHEN lr.completed_count = lr.total_count THEN 'GREEN'
        WHEN lr.has_waiting OR COALESCE(ar.has_yellow_alert, FALSE) THEN 'YELLOW'
        ELSE 'BLUE'
    END AS processing_health,
    lr.completed_count,
    lr.total_count,
    COALESCE(lr.line_exception_reason, ar.first_alert_message) AS attention_reason
FROM line_rollup lr
LEFT JOIN alert_rollup ar ON ar.order_id = lr.order_id;

-- ---------------------------------------------------------------------------
-- Analytics views. All exclude DEMO data and use Asia/Shanghai natural days.
-- ---------------------------------------------------------------------------

CREATE VIEW analytics.v_channel_daily AS
WITH order_metrics AS (
    SELECT
        (o.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(DISTINCT o.id)::BIGINT AS order_count,
        count(ol.id)::BIGINT AS order_line_count,
        count(DISTINCT o.id) FILTER (
            WHERE o.order_status IN ('NEED_REVIEW', 'FULFILLMENT_EXCEPTION', 'SYNC_FAILED')
               OR ol.processing_stage = 'EXCEPTION'
        )::BIGINT AS exception_order_count
    FROM app.orders o
    LEFT JOIN app.order_lines ol ON ol.order_id = o.id
    WHERE o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), shipment_metrics AS (
    SELECT
        (COALESCE(s.shipped_at, s.updated_at) AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        COALESCE(sum(
            CASE
                WHEN ol.line_type = 'CUSTOM_BUNDLE'
                    THEN si.shipped_quantity * olc.quantity_per_bundle
                ELSE si.shipped_quantity
            END
        ), 0)::NUMERIC(18,3) AS actual_shipped_quantity,
        count(DISTINCT s.id) FILTER (WHERE si.shipped_quantity > 0)::BIGINT AS shipment_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.shipment_items si ON si.shipment_id = s.id
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    LEFT JOIN app.order_line_components olc
        ON olc.order_line_id = ol.id AND ol.line_type = 'CUSTOM_BUNDLE'
    WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED')
    GROUP BY 1, 2
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(DISTINCT o.id)::BIGINT AS out_of_stock_order_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), metric_keys AS (
    SELECT metric_date, source_channel FROM order_metrics
    UNION SELECT metric_date, source_channel FROM shipment_metrics
    UNION SELECT metric_date, source_channel FROM procurement_metrics
    UNION SELECT metric_date, source_channel FROM sync_metrics
)
SELECT
    k.metric_date,
    k.source_channel,
    COALESCE(om.order_count, 0) AS order_count,
    COALESCE(om.order_line_count, 0) AS order_line_count,
    COALESCE(sm.actual_shipped_quantity, 0)::NUMERIC(18,3) AS actual_shipped_quantity,
    COALESCE(sm.shipment_count, 0) AS shipment_count,
    COALESCE(om.exception_order_count, 0) AS exception_order_count,
    COALESCE(pm.out_of_stock_order_count, 0) AS out_of_stock_order_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count
FROM metric_keys k
LEFT JOIN order_metrics om USING (metric_date, source_channel)
LEFT JOIN shipment_metrics sm USING (metric_date, source_channel)
LEFT JOIN procurement_metrics pm USING (metric_date, source_channel)
LEFT JOIN sync_metrics sym USING (metric_date, source_channel);

CREATE VIEW analytics.v_product_daily AS
WITH shipped_products AS (
    SELECT
        (s.shipped_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        o.id AS order_id,
        s.id AS shipment_id,
        sku.id AS sku_id,
        sku.sku_code,
        p.id AS product_id,
        p.product_code,
        p.product_name,
        c.id AS category_id,
        c.category_code,
        c.category_name,
        si.shipped_quantity AS shipped_quantity
    FROM app.shipment_items si
    JOIN app.shipments s ON s.id = si.shipment_id AND s.shipment_status IN ('SHIPPED', 'DELIVERED')
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id AND ol.line_type = 'SINGLE'
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.skus sku ON sku.id = ol.sku_id
    JOIN app.products p ON p.id = sku.product_id
    LEFT JOIN app.categories c ON c.id = p.category_id
    WHERE si.shipped_quantity > 0

    UNION ALL

    SELECT
        (s.shipped_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        o.id AS order_id,
        s.id AS shipment_id,
        sku.id AS sku_id,
        sku.sku_code,
        p.id AS product_id,
        p.product_code,
        p.product_name,
        c.id AS category_id,
        c.category_code,
        c.category_name,
        si.shipped_quantity * olc.quantity_per_bundle AS shipped_quantity
    FROM app.shipment_items si
    JOIN app.shipments s ON s.id = si.shipment_id AND s.shipment_status IN ('SHIPPED', 'DELIVERED')
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id AND ol.line_type = 'CUSTOM_BUNDLE'
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.order_line_components olc ON olc.order_line_id = ol.id
    JOIN app.skus sku ON sku.id = olc.sku_id
    JOIN app.products p ON p.id = sku.product_id
    LEFT JOIN app.categories c ON c.id = p.category_id
    WHERE si.shipped_quantity > 0
)
SELECT
    metric_date,
    source_channel,
    category_id,
    category_code,
    category_name,
    product_id,
    product_code,
    product_name,
    sku_id,
    sku_code,
    count(DISTINCT order_id)::BIGINT AS order_count,
    count(DISTINCT shipment_id)::BIGINT AS shipment_count,
    sum(shipped_quantity)::NUMERIC(18,3) AS actual_shipped_quantity
FROM shipped_products
GROUP BY
    metric_date, source_channel,
    category_id, category_code, category_name,
    product_id, product_code, product_name,
    sku_id, sku_code;

CREATE VIEW analytics.v_fulfillment_daily AS
WITH fulfillment_metrics AS (
    SELECT
        (f.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        f.fulfillment_provider_id,
        count(*)::BIGINT AS fulfillment_count,
        COALESCE(sum(f.cumulative_shipped_quantity), 0)::NUMERIC(18,3) AS fulfilled_quantity,
        count(*) FILTER (WHERE f.shipping_progress = 'NOT_SHIPPED')::BIGINT AS not_shipped_count,
        count(*) FILTER (WHERE f.shipping_progress = 'PARTIALLY_SHIPPED')::BIGINT AS partially_shipped_count,
        count(*) FILTER (WHERE f.shipping_progress = 'SHIPPED')::BIGINT AS fully_shipped_count
    FROM app.fulfillments f
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), shipment_metrics AS (
    SELECT
        (s.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE s.shipment_status = 'CREATED')::BIGINT AS awaiting_shipment_count,
        count(*) FILTER (WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED'))::BIGINT AS shipped_shipment_count,
        count(*) FILTER (
            WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED') AND t.id IS NULL
        )::BIGINT AS awaiting_tracking_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    LEFT JOIN app.trackings t ON t.shipment_id = s.id
    GROUP BY 1, 2
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        f.fulfillment_provider_id,
        count(*)::BIGINT AS procurement_ticket_count,
        count(DISTINCT f.id)::BIGINT AS out_of_stock_fulfillment_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count,
        count(*) FILTER (WHERE ss.sync_status = 'PENDING')::BIGINT AS awaiting_sync_count,
        count(*) FILTER (WHERE ss.sync_status = 'SYNCED')::BIGINT AS synced_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), metric_keys AS (
    SELECT metric_date, fulfillment_provider_id FROM fulfillment_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM shipment_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM procurement_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM sync_metrics
)
SELECT
    k.metric_date,
    fp.provider_code,
    fp.provider_name,
    fp.provider_type,
    COALESCE(fm.fulfillment_count, 0) AS fulfillment_count,
    COALESCE(fm.fulfilled_quantity, 0)::NUMERIC(18,3) AS fulfilled_quantity,
    COALESCE(fm.not_shipped_count, 0) AS not_shipped_count,
    COALESCE(fm.partially_shipped_count, 0) AS partially_shipped_count,
    COALESCE(fm.fully_shipped_count, 0) AS fully_shipped_count,
    COALESCE(pm.procurement_ticket_count, 0) AS procurement_ticket_count,
    COALESCE(pm.out_of_stock_fulfillment_count, 0) AS out_of_stock_fulfillment_count,
    COALESCE(sm.awaiting_shipment_count, 0) AS awaiting_shipment_count,
    COALESCE(sm.shipped_shipment_count, 0) AS shipped_shipment_count,
    COALESCE(sm.awaiting_tracking_count, 0) AS awaiting_tracking_count,
    COALESCE(sym.awaiting_sync_count, 0) AS awaiting_sync_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count,
    COALESCE(sym.synced_count, 0) AS synced_count
FROM metric_keys k
JOIN app.fulfillment_providers fp ON fp.id = k.fulfillment_provider_id
LEFT JOIN fulfillment_metrics fm USING (metric_date, fulfillment_provider_id)
LEFT JOIN shipment_metrics sm USING (metric_date, fulfillment_provider_id)
LEFT JOIN procurement_metrics pm USING (metric_date, fulfillment_provider_id)
LEFT JOIN sync_metrics sym USING (metric_date, fulfillment_provider_id);

-- Channel-grained fulfillment facts drive the dashboard's global channel filter.
-- Keep v_fulfillment_daily for provider-level BI compatibility.
CREATE VIEW analytics.v_fulfillment_channel_daily AS
WITH fulfillment_metrics AS (
    SELECT
        (f.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        f.fulfillment_provider_id,
        count(DISTINCT f.id)::BIGINT AS fulfillment_count,
        COALESCE(sum(f.cumulative_shipped_quantity), 0)::NUMERIC(18,3) AS fulfilled_quantity,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'NOT_SHIPPED')::BIGINT AS not_shipped_count,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'PARTIALLY_SHIPPED')::BIGINT AS partially_shipped_count,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'SHIPPED')::BIGINT AS fully_shipped_count
    FROM app.fulfillments f
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), shipment_metrics AS (
    SELECT
        (s.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        s.fulfillment_provider_id,
        count(DISTINCT s.id) FILTER (WHERE s.shipment_status = 'CREATED')::BIGINT AS awaiting_shipment_count,
        count(DISTINCT s.id) FILTER (WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED'))::BIGINT AS shipped_shipment_count,
        count(DISTINCT s.id) FILTER (
            WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED') AND t.id IS NULL
        )::BIGINT AS awaiting_tracking_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    LEFT JOIN app.trackings t ON t.shipment_id = s.id
    GROUP BY 1, 2, 3
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        f.fulfillment_provider_id,
        count(DISTINCT pt.id)::BIGINT AS procurement_ticket_count,
        count(DISTINCT f.id)::BIGINT AS out_of_stock_fulfillment_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count,
        count(*) FILTER (WHERE ss.sync_status = 'PENDING')::BIGINT AS awaiting_sync_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), metric_keys AS (
    SELECT metric_date, source_channel, fulfillment_provider_id FROM fulfillment_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM shipment_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM procurement_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM sync_metrics
)
SELECT
    k.metric_date,
    k.source_channel,
    fp.provider_code,
    fp.provider_name,
    fp.provider_type,
    COALESCE(fm.fulfillment_count, 0) AS fulfillment_count,
    COALESCE(fm.fulfilled_quantity, 0)::NUMERIC(18,3) AS fulfilled_quantity,
    COALESCE(fm.not_shipped_count, 0) AS not_shipped_count,
    COALESCE(fm.partially_shipped_count, 0) AS partially_shipped_count,
    COALESCE(fm.fully_shipped_count, 0) AS fully_shipped_count,
    COALESCE(pm.procurement_ticket_count, 0) AS procurement_ticket_count,
    COALESCE(pm.out_of_stock_fulfillment_count, 0) AS out_of_stock_fulfillment_count,
    COALESCE(sm.awaiting_shipment_count, 0) AS awaiting_shipment_count,
    COALESCE(sm.shipped_shipment_count, 0) AS shipped_shipment_count,
    COALESCE(sm.awaiting_tracking_count, 0) AS awaiting_tracking_count,
    COALESCE(sym.awaiting_sync_count, 0) AS awaiting_sync_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count
FROM metric_keys k
JOIN app.fulfillment_providers fp ON fp.id = k.fulfillment_provider_id
LEFT JOIN fulfillment_metrics fm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN shipment_metrics sm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN procurement_metrics pm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN sync_metrics sym USING (metric_date, source_channel, fulfillment_provider_id);

COMMIT;
-- END V1__baseline.sql

-- BEGIN V2__fix_awaiting_tracking_metric.sql
CREATE OR REPLACE VIEW analytics.v_fulfillment_daily AS
WITH fulfillment_metrics AS (
    SELECT
        (f.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        f.fulfillment_provider_id,
        count(*)::BIGINT AS fulfillment_count,
        COALESCE(sum(f.cumulative_shipped_quantity), 0)::NUMERIC(18,3) AS fulfilled_quantity,
        count(*) FILTER (WHERE f.shipping_progress = 'NOT_SHIPPED')::BIGINT AS not_shipped_count,
        count(*) FILTER (WHERE f.shipping_progress = 'PARTIALLY_SHIPPED')::BIGINT AS partially_shipped_count,
        count(*) FILTER (WHERE f.shipping_progress = 'SHIPPED')::BIGINT AS fully_shipped_count
    FROM app.fulfillments f
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), shipment_metrics AS (
    SELECT
        (s.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE s.shipment_status = 'CREATED')::BIGINT AS awaiting_shipment_count,
        count(*) FILTER (WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED'))::BIGINT AS shipped_shipment_count,
        count(*) FILTER (
            WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED') AND t.id IS NULL
        )::BIGINT AS awaiting_tracking_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    LEFT JOIN app.trackings t ON t.shipment_id = s.id
    GROUP BY 1, 2
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        f.fulfillment_provider_id,
        count(*)::BIGINT AS procurement_ticket_count,
        count(DISTINCT f.id)::BIGINT AS out_of_stock_fulfillment_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count,
        count(*) FILTER (WHERE ss.sync_status = 'PENDING')::BIGINT AS awaiting_sync_count,
        count(*) FILTER (WHERE ss.sync_status = 'SYNCED')::BIGINT AS synced_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), metric_keys AS (
    SELECT metric_date, fulfillment_provider_id FROM fulfillment_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM shipment_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM procurement_metrics
    UNION SELECT metric_date, fulfillment_provider_id FROM sync_metrics
)
SELECT
    k.metric_date,
    fp.provider_code,
    fp.provider_name,
    fp.provider_type,
    COALESCE(fm.fulfillment_count, 0) AS fulfillment_count,
    COALESCE(fm.fulfilled_quantity, 0)::NUMERIC(18,3) AS fulfilled_quantity,
    COALESCE(fm.not_shipped_count, 0) AS not_shipped_count,
    COALESCE(fm.partially_shipped_count, 0) AS partially_shipped_count,
    COALESCE(fm.fully_shipped_count, 0) AS fully_shipped_count,
    COALESCE(pm.procurement_ticket_count, 0) AS procurement_ticket_count,
    COALESCE(pm.out_of_stock_fulfillment_count, 0) AS out_of_stock_fulfillment_count,
    COALESCE(sm.awaiting_shipment_count, 0) AS awaiting_shipment_count,
    COALESCE(sm.shipped_shipment_count, 0) AS shipped_shipment_count,
    COALESCE(sm.awaiting_tracking_count, 0) AS awaiting_tracking_count,
    COALESCE(sym.awaiting_sync_count, 0) AS awaiting_sync_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count,
    COALESCE(sym.synced_count, 0) AS synced_count
FROM metric_keys k
JOIN app.fulfillment_providers fp ON fp.id = k.fulfillment_provider_id
LEFT JOIN fulfillment_metrics fm USING (metric_date, fulfillment_provider_id)
LEFT JOIN shipment_metrics sm USING (metric_date, fulfillment_provider_id)
LEFT JOIN procurement_metrics pm USING (metric_date, fulfillment_provider_id)
LEFT JOIN sync_metrics sym USING (metric_date, fulfillment_provider_id);
-- END V2__fix_awaiting_tracking_metric.sql

-- BEGIN V3__add_channel_fulfillment_analytics.sql
CREATE OR REPLACE VIEW analytics.v_fulfillment_channel_daily AS
WITH fulfillment_metrics AS (
    SELECT
        (f.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        f.fulfillment_provider_id,
        count(DISTINCT f.id)::BIGINT AS fulfillment_count,
        COALESCE(sum(f.cumulative_shipped_quantity), 0)::NUMERIC(18,3) AS fulfilled_quantity,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'NOT_SHIPPED')::BIGINT AS not_shipped_count,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'PARTIALLY_SHIPPED')::BIGINT AS partially_shipped_count,
        count(DISTINCT f.id) FILTER (WHERE f.shipping_progress = 'SHIPPED')::BIGINT AS fully_shipped_count
    FROM app.fulfillments f
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), shipment_metrics AS (
    SELECT
        (s.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        s.fulfillment_provider_id,
        count(DISTINCT s.id) FILTER (WHERE s.shipment_status = 'CREATED')::BIGINT AS awaiting_shipment_count,
        count(DISTINCT s.id) FILTER (WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED'))::BIGINT AS shipped_shipment_count,
        count(DISTINCT s.id) FILTER (
            WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED') AND t.id IS NULL
        )::BIGINT AS awaiting_tracking_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    LEFT JOIN app.trackings t ON t.shipment_id = s.id
    GROUP BY 1, 2, 3
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        f.fulfillment_provider_id,
        count(DISTINCT pt.id)::BIGINT AS procurement_ticket_count,
        count(DISTINCT f.id)::BIGINT AS out_of_stock_fulfillment_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        s.fulfillment_provider_id,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count,
        count(*) FILTER (WHERE ss.sync_status = 'PENDING')::BIGINT AS awaiting_sync_count,
        count(*) FILTER (WHERE ss.sync_status = 'SYNCED')::BIGINT AS synced_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2, 3
), metric_keys AS (
    SELECT metric_date, source_channel, fulfillment_provider_id FROM fulfillment_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM shipment_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM procurement_metrics
    UNION SELECT metric_date, source_channel, fulfillment_provider_id FROM sync_metrics
)
SELECT
    k.metric_date,
    k.source_channel,
    fp.provider_code,
    fp.provider_name,
    fp.provider_type,
    COALESCE(fm.fulfillment_count, 0) AS fulfillment_count,
    COALESCE(fm.fulfilled_quantity, 0)::NUMERIC(18,3) AS fulfilled_quantity,
    COALESCE(fm.not_shipped_count, 0) AS not_shipped_count,
    COALESCE(fm.partially_shipped_count, 0) AS partially_shipped_count,
    COALESCE(fm.fully_shipped_count, 0) AS fully_shipped_count,
    COALESCE(pm.procurement_ticket_count, 0) AS procurement_ticket_count,
    COALESCE(pm.out_of_stock_fulfillment_count, 0) AS out_of_stock_fulfillment_count,
    COALESCE(sm.awaiting_shipment_count, 0) AS awaiting_shipment_count,
    COALESCE(sm.shipped_shipment_count, 0) AS shipped_shipment_count,
    COALESCE(sm.awaiting_tracking_count, 0) AS awaiting_tracking_count,
    COALESCE(sym.awaiting_sync_count, 0) AS awaiting_sync_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count,
    COALESCE(sym.synced_count, 0) AS synced_count
FROM metric_keys k
JOIN app.fulfillment_providers fp ON fp.id = k.fulfillment_provider_id
LEFT JOIN fulfillment_metrics fm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN shipment_metrics sm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN procurement_metrics pm USING (metric_date, source_channel, fulfillment_provider_id)
LEFT JOIN sync_metrics sym USING (metric_date, source_channel, fulfillment_provider_id);
-- END V3__add_channel_fulfillment_analytics.sql

