-- BEGIN V6__allow_unknown_shipped_at.sql
DO $$
DECLARE
    constraint_name TEXT;
BEGIN
    SELECT conname
    INTO constraint_name
    FROM pg_constraint
    WHERE conrelid = 'app.shipments'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%shipped_at IS NOT NULL%';

    IF constraint_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE app.shipments DROP CONSTRAINT %I', constraint_name);
    END IF;
END
$$;

ALTER TABLE app.shipments
    DROP CONSTRAINT IF EXISTS shipments_shipped_at_consistency;

ALTER TABLE app.shipments
    ADD CONSTRAINT shipments_shipped_at_consistency
        CHECK (shipment_status IN ('SHIPPED', 'DELIVERED') OR shipped_at IS NULL);

CREATE OR REPLACE VIEW analytics.v_channel_daily AS
WITH order_metrics AS (
    SELECT
        (o.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(DISTINCT o.id)::BIGINT AS order_count,
        count(ol.id)::BIGINT AS order_line_count,
        count(DISTINCT o.id) FILTER (
            WHERE o.order_status IN ('NEED_REVIEW', 'FULFILLMENT_EXCEPTION', 'SYNC_FAILED')
               OR ol.processing_stage = 'EXCEPTION'
        )::BIGINT AS exception_order_count
    FROM app.orders o
    LEFT JOIN app.order_lines ol ON ol.order_id = o.id
    WHERE o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), shipment_metrics AS (
    SELECT
        (s.shipped_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        COALESCE(sum(
            CASE
                WHEN ol.line_type = 'CUSTOM_BUNDLE'
                    THEN si.shipped_quantity * olc.quantity_per_bundle
                ELSE si.shipped_quantity
            END
        ), 0)::NUMERIC(18,3) AS actual_shipped_quantity,
        count(DISTINCT s.id) FILTER (WHERE si.shipped_quantity > 0)::BIGINT AS shipment_count
    FROM app.shipments s
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.shipment_items si ON si.shipment_id = s.id
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    LEFT JOIN app.order_line_components olc
        ON olc.order_line_id = ol.id AND ol.line_type = 'CUSTOM_BUNDLE'
    WHERE s.shipment_status IN ('SHIPPED', 'DELIVERED')
      AND s.shipped_at IS NOT NULL
    GROUP BY 1, 2
), procurement_metrics AS (
    SELECT
        (pt.created_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(DISTINCT o.id)::BIGINT AS out_of_stock_order_count
    FROM app.procurement_tickets pt
    JOIN app.fulfillments f ON f.id = pt.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), sync_metrics AS (
    SELECT
        (ss.updated_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        count(*) FILTER (WHERE ss.sync_status = 'SYNC_FAILED')::BIGINT AS sync_failed_count
    FROM app.shipment_syncs ss
    JOIN app.shipments s ON s.id = ss.shipment_id
    JOIN app.orders o ON o.id = s.order_id AND o.data_scope = 'BUSINESS'
    GROUP BY 1, 2
), metric_keys AS (
    SELECT metric_date, source_channel FROM order_metrics
    UNION SELECT metric_date, source_channel FROM shipment_metrics
    UNION SELECT metric_date, source_channel FROM procurement_metrics
    UNION SELECT metric_date, source_channel FROM sync_metrics
)
SELECT
    k.metric_date,
    k.source_channel,
    COALESCE(om.order_count, 0) AS order_count,
    COALESCE(om.order_line_count, 0) AS order_line_count,
    COALESCE(sm.actual_shipped_quantity, 0)::NUMERIC(18,3) AS actual_shipped_quantity,
    COALESCE(sm.shipment_count, 0) AS shipment_count,
    COALESCE(om.exception_order_count, 0) AS exception_order_count,
    COALESCE(pm.out_of_stock_order_count, 0) AS out_of_stock_order_count,
    COALESCE(sym.sync_failed_count, 0) AS sync_failed_count
FROM metric_keys k
LEFT JOIN order_metrics om USING (metric_date, source_channel)
LEFT JOIN shipment_metrics sm USING (metric_date, source_channel)
LEFT JOIN procurement_metrics pm USING (metric_date, source_channel)
LEFT JOIN sync_metrics sym USING (metric_date, source_channel);

CREATE OR REPLACE VIEW analytics.v_product_daily AS
WITH shipped_products AS (
    SELECT
        (s.shipped_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        o.id AS order_id,
        s.id AS shipment_id,
        sku.id AS sku_id,
        sku.sku_code,
        p.id AS product_id,
        p.product_code,
        p.product_name,
        c.id AS category_id,
        c.category_code,
        c.category_name,
        si.shipped_quantity AS shipped_quantity
    FROM app.shipment_items si
    JOIN app.shipments s ON s.id = si.shipment_id AND s.shipment_status IN ('SHIPPED', 'DELIVERED')
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id AND ol.line_type = 'SINGLE'
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.skus sku ON sku.id = ol.sku_id
    JOIN app.products p ON p.id = sku.product_id
    LEFT JOIN app.categories c ON c.id = p.category_id
    WHERE si.shipped_quantity > 0
      AND s.shipped_at IS NOT NULL

    UNION ALL

    SELECT
        (s.shipped_at AT TIME ZONE 'Asia/Shanghai')::DATE AS metric_date,
        o.source_channel,
        o.id AS order_id,
        s.id AS shipment_id,
        sku.id AS sku_id,
        sku.sku_code,
        p.id AS product_id,
        p.product_code,
        p.product_name,
        c.id AS category_id,
        c.category_code,
        c.category_name,
        si.shipped_quantity * olc.quantity_per_bundle AS shipped_quantity
    FROM app.shipment_items si
    JOIN app.shipments s ON s.id = si.shipment_id AND s.shipment_status IN ('SHIPPED', 'DELIVERED')
    JOIN app.fulfillments f ON f.id = si.fulfillment_id
    JOIN app.order_lines ol ON ol.id = f.order_line_id AND ol.line_type = 'CUSTOM_BUNDLE'
    JOIN app.orders o ON o.id = ol.order_id AND o.data_scope = 'BUSINESS'
    JOIN app.order_line_components olc ON olc.order_line_id = ol.id
    JOIN app.skus sku ON sku.id = olc.sku_id
    JOIN app.products p ON p.id = sku.product_id
    LEFT JOIN app.categories c ON c.id = p.category_id
    WHERE si.shipped_quantity > 0
      AND s.shipped_at IS NOT NULL
)
SELECT
    metric_date,
    source_channel,
    category_id,
    category_code,
    category_name,
    product_id,
    product_code,
    product_name,
    sku_id,
    sku_code,
    count(DISTINCT order_id)::BIGINT AS order_count,
    count(DISTINCT shipment_id)::BIGINT AS shipment_count,
    sum(shipped_quantity)::NUMERIC(18,3) AS actual_shipped_quantity
FROM shipped_products
GROUP BY
    metric_date, source_channel,
    category_id, category_code, category_name,
    product_id, product_code, product_name,
    sku_id, sku_code;
-- END V6__allow_unknown_shipped_at.sql

-- BEGIN V7__add_channel_messages.sql
CREATE TABLE IF NOT EXISTS app.channel_messages (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    channel             VARCHAR(32) NOT NULL DEFAULT 'WECOM' CHECK (channel = 'WECOM'),
    corp_id             VARCHAR(128) NOT NULL,
    connection_id       VARCHAR(128) NOT NULL,
    bot_id              VARCHAR(128) NOT NULL,
    message_id          VARCHAR(255) NOT NULL,
    chat_id             VARCHAR(255) NOT NULL,
    chat_type           VARCHAR(32) NOT NULL CHECK (chat_type IN ('group', 'single')),
    sender_user_id      VARCHAR(255) NOT NULL,
    message_type        VARCHAR(32) NOT NULL,
    content             TEXT NOT NULL,
    quote_type          VARCHAR(32),
    quote_content       TEXT,
    raw_payload         JSONB NOT NULL CHECK (jsonb_typeof(raw_payload) = 'object'),
    received_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (corp_id, connection_id, message_id),
    CHECK (btrim(corp_id) <> ''),
    CHECK (btrim(connection_id) <> ''),
    CHECK (btrim(bot_id) <> ''),
    CHECK (btrim(message_id) <> ''),
    CHECK (btrim(chat_id) <> ''),
    CHECK (btrim(sender_user_id) <> ''),
    CHECK (btrim(message_type) <> '')
);

CREATE INDEX IF NOT EXISTS idx_channel_messages_received
    ON app.channel_messages (received_at DESC, id DESC);
-- END V7__add_channel_messages.sql

-- BEGIN V8__add_message_pipeline.sql
-- ---------------------------------------------------------------------------
-- 企业微信消息管线：异步任务、提交、解释、媒体、草稿与渠道身份
-- 一期所有表在此一次性建立，后续票只增加 Java 层实现，不再扩展 schema 冲突面。
-- ---------------------------------------------------------------------------

CREATE TABLE app.async_tasks (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_type           VARCHAR(64) NOT NULL CHECK (btrim(task_type) <> ''),
    payload_ref         VARCHAR(512) NOT NULL CHECK (btrim(payload_ref) <> ''),
    status              VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                        CHECK (status IN ('PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    attempts            INT NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts        INT NOT NULL DEFAULT 3 CHECK (max_attempts >= 1),
    next_run_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_until         TIMESTAMPTZ,
    lease_owner         VARCHAR(128),
    last_error          TEXT,
    idempotency_key     VARCHAR(255) NOT NULL UNIQUE CHECK (btrim(idempotency_key) <> ''),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_async_tasks_due
    ON app.async_tasks (status, next_run_at, id)
    WHERE status IN ('PENDING', 'RUNNING');

CREATE TABLE app.message_submissions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    submission_no       VARCHAR(64) NOT NULL UNIQUE CHECK (btrim(submission_no) <> ''),
    source_message_id   BIGINT NOT NULL REFERENCES app.channel_messages(id) ON DELETE RESTRICT,
    status              VARCHAR(16) NOT NULL DEFAULT 'RECEIVED'
                        CHECK (status IN ('RECEIVED', 'INTERPRETED', 'FAILED', 'DRAFTED', 'CONFIRMED', 'REJECTED')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_message_submissions_message
    ON app.message_submissions (source_message_id);

CREATE TABLE app.message_media (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    submission_id       BIGINT REFERENCES app.message_submissions(id) ON DELETE RESTRICT,
    channel_message_id  BIGINT REFERENCES app.channel_messages(id) ON DELETE RESTRICT,
    channel_media_id    VARCHAR(255) NOT NULL CHECK (btrim(channel_media_id) <> ''),
    media_type          VARCHAR(32) NOT NULL CHECK (media_type IN ('image', 'file', 'voice', 'video')),
    download_status     VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                        CHECK (download_status IN ('PENDING', 'DOWNLOADING', 'AVAILABLE', 'FAILED')),
    content_ref         VARCHAR(512),
    content_hash        VARCHAR(128),
    content_type        VARCHAR(128),
    size_bytes          BIGINT CHECK (size_bytes IS NULL OR size_bytes >= 0),
    decrypt_info        JSONB,
    failure_reason      TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (channel_message_id, channel_media_id),
    CHECK (num_nonnulls(submission_id, channel_message_id) > 0)
);

CREATE INDEX idx_message_media_submission ON app.message_media (submission_id);
CREATE INDEX idx_message_media_download ON app.message_media (download_status, id);

CREATE TABLE app.message_interpretations (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    submission_id       BIGINT NOT NULL REFERENCES app.message_submissions(id) ON DELETE RESTRICT,
    version             INT NOT NULL CHECK (version >= 1),
    provider            VARCHAR(128) NOT NULL CHECK (btrim(provider) <> ''),
    model               VARCHAR(128) NOT NULL CHECK (btrim(model) <> ''),
    prompt_version      VARCHAR(64) NOT NULL CHECK (btrim(prompt_version) <> ''),
    intent              VARCHAR(32) NOT NULL
                        CHECK (intent IN ('CUSTOMER_ORDER', 'SUPPLIER_TRACKING', 'ORDER_CHANGE',
                                          'ORDER_CANCEL', 'NON_BUSINESS', 'NEED_REVIEW')),
    structured_output   JSONB NOT NULL DEFAULT '{}'::JSONB CHECK (jsonb_typeof(structured_output) = 'object'),
    error               TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (submission_id, version)
);

CREATE INDEX idx_message_interpretations_submission
    ON app.message_interpretations (submission_id, version DESC);

CREATE TABLE app.order_drafts (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    draft_no             VARCHAR(64) NOT NULL UNIQUE CHECK (btrim(draft_no) <> ''),
    submission_id        BIGINT NOT NULL REFERENCES app.message_submissions(id) ON DELETE RESTRICT,
    source_order_no      VARCHAR(128) NOT NULL CHECK (btrim(source_order_no) <> ''),
    customer_id          BIGINT REFERENCES app.customers(id) ON DELETE RESTRICT,
    customer_candidates  JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(customer_candidates) = 'array'),
    customer_name_raw    TEXT,
    receiver_name        TEXT,
    receiver_phone       TEXT,
    receiver_address     TEXT,
    settlement_method    VARCHAR(32),
    missing_fields       JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(missing_fields) = 'array'),
    status               VARCHAR(16) NOT NULL DEFAULT 'OPEN'
                         CHECK (status IN ('OPEN', 'CONFIRMED', 'REJECTED')),
    revision             BIGINT NOT NULL DEFAULT 0 CHECK (revision >= 0),
    confirmed_by         VARCHAR(128),
    confirmed_at         TIMESTAMPTZ,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        (status = 'OPEN' AND confirmed_by IS NULL AND confirmed_at IS NULL)
        OR (status IN ('CONFIRMED', 'REJECTED') AND confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL)
    )
);

CREATE INDEX idx_order_drafts_submission ON app.order_drafts (submission_id);
CREATE INDEX idx_order_drafts_status ON app.order_drafts (status, created_at DESC);

CREATE TABLE app.order_draft_lines (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_draft_id       BIGINT NOT NULL REFERENCES app.order_drafts(id) ON DELETE RESTRICT,
    line_no              INT NOT NULL CHECK (line_no >= 1),
    sku_id               BIGINT REFERENCES app.skus(id) ON DELETE RESTRICT,
    sku_candidates       JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(sku_candidates) = 'array'),
    product_name_raw     TEXT,
    spec_raw             TEXT,
    unit_raw             TEXT,
    quantity             NUMERIC(18, 3) CHECK (quantity IS NULL OR quantity > 0),
    fulfilled_quantity   NUMERIC(18, 3) NOT NULL DEFAULT 0 CHECK (fulfilled_quantity >= 0),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (order_draft_id, line_no)
);

CREATE INDEX idx_order_draft_lines_draft ON app.order_draft_lines (order_draft_id);

CREATE TABLE app.provider_tracking_drafts (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    draft_no              VARCHAR(64) NOT NULL UNIQUE CHECK (btrim(draft_no) <> ''),
    submission_id         BIGINT NOT NULL REFERENCES app.message_submissions(id) ON DELETE RESTRICT,
    line_no               INT NOT NULL CHECK (line_no >= 1),
    raw_receiver_name     TEXT,
    masked_receiver_name  TEXT,
    tracking_no           VARCHAR(128),
    carrier_code          VARCHAR(64),
    carrier_candidates    JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(carrier_candidates) = 'array'),
    task_id               BIGINT REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    task_candidates       JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(task_candidates) = 'array'),
    shipment_judgment     VARCHAR(32) NOT NULL DEFAULT 'FULL'
                          CHECK (shipment_judgment IN ('FULL', 'PARTIAL', 'SHORTAGE', 'EXCEPTION')),
    actual_quantity       NUMERIC(18, 3) CHECK (actual_quantity IS NULL OR actual_quantity >= 0),
    validation_issues     JSONB NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(validation_issues) = 'array'),
    status                VARCHAR(16) NOT NULL DEFAULT 'OPEN'
                          CHECK (status IN ('OPEN', 'CONFIRMED', 'REJECTED')),
    revision              BIGINT NOT NULL DEFAULT 0 CHECK (revision >= 0),
    confirmed_by          VARCHAR(128),
    confirmed_at          TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        (status = 'OPEN' AND confirmed_by IS NULL AND confirmed_at IS NULL)
        OR (status IN ('CONFIRMED', 'REJECTED') AND confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL)
    )
);

CREATE INDEX idx_tracking_drafts_submission ON app.provider_tracking_drafts (submission_id);
CREATE INDEX idx_tracking_drafts_status ON app.provider_tracking_drafts (status, created_at DESC);
CREATE INDEX idx_tracking_drafts_task ON app.provider_tracking_drafts (task_id) WHERE task_id IS NOT NULL;

CREATE TABLE app.channel_identities (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    corp_id             VARCHAR(128) NOT NULL CHECK (btrim(corp_id) <> ''),
    access_type         VARCHAR(64) NOT NULL CHECK (btrim(access_type) <> ''),
    channel_identity    VARCHAR(255) NOT NULL CHECK (btrim(channel_identity) <> ''),
    customer_id         BIGINT REFERENCES app.customers(id) ON DELETE RESTRICT,
    display_name        VARCHAR(255),
    remark              TEXT,
    description         TEXT,
    avatar_url          VARCHAR(512),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (corp_id, access_type, channel_identity)
);

CREATE INDEX idx_channel_identities_customer ON app.channel_identities (customer_id);

-- ---------------------------------------------------------------------------
-- review_cases 扩展：草稿主体引用与“恰好一个主体”约束
-- 老业务主体（order/order_line/fulfillment/shipment/import_batch/raw_import_row）
-- 保持原有“至少一个”语义；新草稿主体（submission/order_draft/tracking_draft）
-- 必须恰好一个且不与业务主体混用。
-- ---------------------------------------------------------------------------

ALTER TABLE app.review_cases
    ADD COLUMN message_submission_id BIGINT REFERENCES app.message_submissions(id) ON DELETE RESTRICT,
    ADD COLUMN order_draft_id BIGINT REFERENCES app.order_drafts(id) ON DELETE RESTRICT,
    ADD COLUMN provider_tracking_draft_id BIGINT REFERENCES app.provider_tracking_drafts(id) ON DELETE RESTRICT;

-- 移除 V1 的“至少一个业务主体”检查，替换为新的双分支检查
DO $$
DECLARE
    con_name TEXT;
BEGIN
    SELECT conname INTO con_name
    FROM pg_constraint
    WHERE conrelid = 'app.review_cases'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%num_nonnulls%';
    IF con_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE app.review_cases DROP CONSTRAINT %I', con_name);
    END IF;
END $$;

ALTER TABLE app.review_cases
    ADD CONSTRAINT review_cases_subject_check CHECK (
        (
            num_nonnulls(order_id, order_line_id, fulfillment_id, shipment_id,
                         import_batch_id, raw_import_row_id) > 0
            AND num_nonnulls(message_submission_id, order_draft_id, provider_tracking_draft_id) = 0
        )
        OR
        (
            num_nonnulls(order_id, order_line_id, fulfillment_id, shipment_id,
                         import_batch_id, raw_import_row_id) = 0
            AND num_nonnulls(message_submission_id, order_draft_id, provider_tracking_draft_id) = 1
        )
    );

-- 开放事项唯一性扩展到草稿主体
DROP INDEX app.uq_review_case_open_subject_reason;
CREATE UNIQUE INDEX uq_review_case_open_subject_reason ON app.review_cases(
    reason_code,
    (COALESCE(order_id, 0)),
    (COALESCE(order_line_id, 0)),
    (COALESCE(fulfillment_id, 0)),
    (COALESCE(shipment_id, 0)),
    (COALESCE(import_batch_id, 0)),
    (COALESCE(raw_import_row_id, 0)),
    (COALESCE(message_submission_id, 0)),
    (COALESCE(order_draft_id, 0)),
    (COALESCE(provider_tracking_draft_id, 0))
) WHERE status = 'OPEN';

CREATE INDEX idx_review_cases_submission ON app.review_cases (message_submission_id);
CREATE INDEX idx_review_cases_order_draft ON app.review_cases (order_draft_id);
CREATE INDEX idx_review_cases_tracking_draft ON app.review_cases (provider_tracking_draft_id);
-- END V8__add_message_pipeline.sql

-- BEGIN V9__jd_fulfillment_sync.sql
-- ---------------------------------------------------------------------------
-- 京东云仓履约闭环：Shipment 级京东出库集成记录
-- ---------------------------------------------------------------------------
-- 本迁移在发布前被纠正：旧版本向 app.fulfillments 追加 jd_erp_delivery_no / jd_sync_status
-- （按逐行 Fulfillment 承载京东出库单号与同步状态），违反「一个 Shipment 最多一张京东出库单」
-- 的批次边界，也会把 JD 集成状态与 OrderLine 权威 processing_stage 混在一起。
-- 旧文件从未提交/发布（仅存在于本地工作区），因此直接原地纠正，不做 expand-migrate-contract。
--
-- 新边界（jd-fulfillment-loop/01）：
--   * app.shipment_jd_outbounds 与 app.shipments 一对一，同批次全部 ShipmentItem/Fulfillment 共享；
--   * erp_delivery_no = shipments.outbound_order_no（系统生成的稳定商户侧出库引用，提交给京东作 erpDeliveryNo）；
--   * sync_status / failure_phase / retry_count / last_error_* / request_hash 均为 JD 集成状态，
--     与 OrderLine processing_stage（权威业务阶段）完全分离。
-- ---------------------------------------------------------------------------

CREATE TABLE app.shipment_jd_outbounds (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shipment_id         BIGINT NOT NULL UNIQUE REFERENCES app.shipments(id) ON DELETE RESTRICT,
    erp_delivery_no     VARCHAR(64) NOT NULL UNIQUE,
    jd_delivery_no      VARCHAR(64),
    sync_status         VARCHAR(32) NOT NULL DEFAULT 'NONE'
                        CHECK (sync_status IN ('NONE', 'SUBMITTING', 'SUBMITTED', 'SYNC_FAILED')),
    failure_phase       VARCHAR(32)
                        CHECK (failure_phase IS NULL OR failure_phase IN ('VALIDATION', 'SUBMIT')),
    retry_count         INTEGER NOT NULL DEFAULT 0 CHECK (retry_count >= 0),
    last_error_code     VARCHAR(64),
    last_error_message  TEXT,
    request_hash        CHAR(64),
    submitted_at        TIMESTAMPTZ,
    last_query_at       TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (btrim(erp_delivery_no) <> ''),
    CHECK (request_hash IS NULL OR request_hash ~ '^[0-9a-f]{64}$'),
    CHECK ((last_error_code IS NULL) = (last_error_message IS NULL)),
    CHECK (sync_status <> 'SUBMITTED' OR submitted_at IS NOT NULL),
    CHECK (sync_status <> 'SYNC_FAILED' OR (failure_phase IS NOT NULL AND last_error_code IS NOT NULL)),
    CHECK (sync_status <> 'SUBMITTING' OR (request_hash IS NOT NULL AND retry_count > 0))
);

CREATE INDEX idx_shipment_jd_outbounds_sync
    ON app.shipment_jd_outbounds (sync_status)
    WHERE sync_status <> 'NONE';
-- END V9__jd_fulfillment_sync.sql

