-- BEGIN V16__allow_external_jd_stock_observations.sql
CREATE OR REPLACE FUNCTION app.validate_stock_snapshot() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    managed BOOLEAN;
    provider_kind VARCHAR(32);
    sku_provider_id BIGINT;
BEGIN
    SELECT inventory_managed_by_us, provider_type INTO STRICT managed, provider_kind
    FROM app.fulfillment_providers WHERE id = NEW.fulfillment_provider_id;

    IF NOT managed AND NOT (
        provider_kind = 'JD_WAREHOUSE'
        AND NEW.quantity_unit = 'JD_PIECE'
        AND NEW.source_type = 'JD_ISC_QUERY_STOCK'
    ) THEN
        RAISE EXCEPTION 'third-party inventory is outside this system';
    END IF;

    SELECT fulfillment_provider_id INTO STRICT sku_provider_id
    FROM app.skus WHERE id = NEW.sku_id;
    IF sku_provider_id <> NEW.fulfillment_provider_id THEN
        RAISE EXCEPTION 'stock snapshot provider does not own SKU';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION app.validate_stock_snapshot() IS
    'Allows managed internal stock facts and classified read-only JD_WAREHOUSE observations; other third-party inventory remains outside this system.';
-- END V16__allow_external_jd_stock_observations.sql

-- BEGIN V17__persist_jd_outbound_client_mode.sql
-- 持久化每次 JD 出库建单尝试的实际 client mode，避免进程从 MOCK 切到 REAL 后
-- 把历史 Mock 结果误标为真实京东验收。旧记录无可靠来源，故 fail closed 保留 UNKNOWN。
ALTER TABLE app.shipment_jd_outbounds
    ADD COLUMN client_mode VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN'
        CHECK (client_mode IN ('UNKNOWN', 'MOCK', 'REAL'));
-- END V17__persist_jd_outbound_client_mode.sql

-- BEGIN V18__add_jd_tracking_backfill_state.sql
-- Ticket 06: preserve the exact non-PII cargo facts submitted to JD and keep
-- tracking-query diagnostics separate from the outbound-create state machine.
ALTER TABLE app.shipment_jd_outbounds
    ADD COLUMN submitted_cargo_snapshot JSONB,
    ADD COLUMN submitted_warehouse_no VARCHAR(128),
    ADD COLUMN tracking_query_status VARCHAR(32) NOT NULL DEFAULT 'NOT_QUERIED',
    ADD COLUMN tracking_query_attempt_count INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN tracking_last_query_at TIMESTAMPTZ,
    ADD COLUMN tracking_last_error_code VARCHAR(64),
    ADD COLUMN tracking_last_error_message TEXT,
    ADD COLUMN tracking_last_request_id VARCHAR(128),
    ADD CONSTRAINT shipment_jd_outbounds_cargo_snapshot_shape CHECK (
        submitted_cargo_snapshot IS NULL OR jsonb_typeof(submitted_cargo_snapshot) = 'array'),
    ADD CONSTRAINT shipment_jd_outbounds_tracking_query_status_check CHECK (
        tracking_query_status IN ('NOT_QUERIED', 'PENDING', 'PARTIAL', 'TRACKED', 'CONFLICT', 'QUERY_FAILED')),
    ADD CONSTRAINT shipment_jd_outbounds_tracking_attempt_count_check CHECK (
        tracking_query_attempt_count >= 0),
    ADD CONSTRAINT shipment_jd_outbounds_tracking_error_pair_check CHECK (
        (tracking_last_error_code IS NULL) = (tracking_last_error_message IS NULL));

-- History before V18 has no trustworthy submitted cargo detail.  It remains
-- NULL and therefore fails closed for automatic tracking backfill.
COMMENT ON COLUMN app.shipment_jd_outbounds.submitted_cargo_snapshot IS
    'Exact non-PII orderLine/goodsNo/planQuantity facts submitted to JD; NULL history cannot auto-backfill';
COMMENT ON COLUMN app.shipment_jd_outbounds.submitted_warehouse_no IS
    'Exact JD warehouseNo submitted with the outbound order; NULL history cannot auto-backfill';

CREATE INDEX idx_shipment_jd_outbounds_tracking_poll
    ON app.shipment_jd_outbounds (client_mode, tracking_last_query_at, shipment_id)
    WHERE sync_status = 'SUBMITTED' AND tracking_query_status <> 'TRACKED';
-- END V18__add_jd_tracking_backfill_state.sql

-- BEGIN V19__add_async_task_finalization_state.sql
-- 模型尝试耗尽后，先持久化可恢复的收口意图；任务 FAILED 与 NEED_REVIEW 仍在同一事务内提交。
ALTER TABLE app.async_tasks
    DROP CONSTRAINT async_tasks_status_check;

ALTER TABLE app.async_tasks
    ADD CONSTRAINT async_tasks_status_check
    CHECK (status IN ('PENDING', 'RUNNING', 'FINALIZING', 'SUCCEEDED', 'FAILED'));

DROP INDEX app.idx_async_tasks_due;

CREATE INDEX idx_async_tasks_due
    ON app.async_tasks (status, next_run_at, id)
    WHERE status IN ('PENDING', 'RUNNING', 'FINALIZING');
-- END V19__add_async_task_finalization_state.sql

-- BEGIN V20__sanitize_wecom_message_public_history.sql
-- V8-V19 allowed free-form model/SDK errors. Before those rows are served by the
-- management API, collapse errors to stable codes and rebuild message-submission
-- ReviewCase detail from an explicit allowlist.

UPDATE app.async_tasks
SET last_error = CASE
        WHEN last_error IS NULL OR btrim(last_error) = '' THEN NULL
        WHEN btrim(last_error) IN
             ('MODEL_NOT_CONFIGURED', 'MODEL_CALL_FAILED', 'MODEL_OUTPUT_INVALID')
            THEN btrim(last_error)
        ELSE 'MODEL_CALL_FAILED'
    END,
    updated_at = CURRENT_TIMESTAMP
WHERE task_type = 'INTERPRET_MESSAGE'
  AND last_error IS DISTINCT FROM CASE
        WHEN last_error IS NULL OR btrim(last_error) = '' THEN NULL
        WHEN btrim(last_error) IN
             ('MODEL_NOT_CONFIGURED', 'MODEL_CALL_FAILED', 'MODEL_OUTPUT_INVALID')
            THEN btrim(last_error)
        ELSE 'MODEL_CALL_FAILED'
    END;

UPDATE app.message_interpretations
SET error = CASE
        WHEN error IS NULL OR btrim(error) = '' THEN NULL
        WHEN btrim(error) IN
             ('MODEL_NOT_CONFIGURED', 'MODEL_CALL_FAILED', 'MODEL_OUTPUT_INVALID')
            THEN btrim(error)
        ELSE 'MODEL_CALL_FAILED'
    END
WHERE error IS DISTINCT FROM CASE
        WHEN error IS NULL OR btrim(error) = '' THEN NULL
        WHEN btrim(error) IN
             ('MODEL_NOT_CONFIGURED', 'MODEL_CALL_FAILED', 'MODEL_OUTPUT_INVALID')
            THEN btrim(error)
        ELSE 'MODEL_CALL_FAILED'
    END;

WITH review_history AS (
    SELECT rc.id,
           rc.detail,
           COALESCE(
               NULLIF(btrim(rc.detail ->> 'error_code'), ''),
               NULLIF(btrim(rc.detail ->> 'error'), ''),
               NULLIF(btrim(rc.detail ->> 'last_error'), ''),
               NULLIF(btrim(rc.detail ->> 'error_message'), ''),
               NULLIF(btrim(rc.detail ->> 'exception_message'), '')
           ) AS error_candidate,
           (
               SELECT COALESCE(jsonb_agg(entry.item ORDER BY entry.ordinal), '[]'::jsonb)
               FROM jsonb_array_elements(
                   CASE
                       WHEN jsonb_typeof(rc.detail #> '{model_output,names}') = 'array'
                           THEN rc.detail #> '{model_output,names}'
                       ELSE '[]'::jsonb
                   END
               ) WITH ORDINALITY AS entry(item, ordinal)
               WHERE entry.ordinal <= 100
                 AND jsonb_typeof(entry.item) IN ('string', 'number', 'boolean')
                 AND char_length(btrim(entry.item #>> '{}')) BETWEEN 1 AND 256
           ) AS names,
           (
               SELECT COALESCE(jsonb_agg(entry.item ORDER BY entry.ordinal), '[]'::jsonb)
               FROM jsonb_array_elements(
                   CASE
                       WHEN jsonb_typeof(rc.detail #> '{model_output,tracking_nos}') = 'array'
                           THEN rc.detail #> '{model_output,tracking_nos}'
                       ELSE '[]'::jsonb
                   END
               ) WITH ORDINALITY AS entry(item, ordinal)
               WHERE entry.ordinal <= 100
                 AND jsonb_typeof(entry.item) IN ('string', 'number', 'boolean')
                 AND char_length(btrim(entry.item #>> '{}')) BETWEEN 1 AND 256
           ) AS tracking_nos
    FROM app.review_cases rc
    WHERE rc.message_submission_id IS NOT NULL
      AND rc.reason_code IN ('WECOM_NEED_REVIEW', 'WECOM_ORDER_CHANGE', 'WECOM_ORDER_CANCEL')
), sanitized AS (
    SELECT id,
           '{}'::jsonb
           || CASE
                WHEN detail ->> 'intent' IN
                     ('CUSTOMER_ORDER', 'SUPPLIER_TRACKING', 'ORDER_CHANGE',
                      'ORDER_CANCEL', 'NON_BUSINESS', 'NEED_REVIEW')
                    THEN jsonb_build_object('intent', detail ->> 'intent')
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN detail ->> 'provider' ~ '^[A-Za-z0-9._:/@+-]{1,128}$'
                    THEN jsonb_build_object('provider', detail ->> 'provider')
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN detail ->> 'model' ~ '^[A-Za-z0-9._:/@+-]{1,128}$'
                    THEN jsonb_build_object('model', detail ->> 'model')
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN detail ->> 'prompt_version' ~ '^[A-Za-z0-9._:/@+-]{1,64}$'
                    THEN jsonb_build_object('prompt_version', detail ->> 'prompt_version')
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN error_candidate IS NOT NULL THEN jsonb_build_object(
                    'error_code',
                    CASE
                        WHEN error_candidate IN
                             ('MODEL_NOT_CONFIGURED', 'MODEL_CALL_FAILED', 'MODEL_OUTPUT_INVALID')
                            THEN error_candidate
                        ELSE 'MODEL_CALL_FAILED'
                    END)
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN char_length(btrim(detail ->> 'order_no')) BETWEEN 3 AND 100
                 AND btrim(detail ->> 'order_no') ~ '^[A-Za-z0-9]+([._/-][A-Za-z0-9]+)*$'
                 AND btrim(detail ->> 'order_no') !~ '^1[3-9][0-9]{9}$'
                    THEN jsonb_build_object('order_no', btrim(detail ->> 'order_no'))
                ELSE '{}'::jsonb
              END
           || CASE
                WHEN detail ->> 'reason' = 'LINE_PAIRING_UNRESOLVED' THEN
                    jsonb_build_object(
                        'reason', 'LINE_PAIRING_UNRESOLVED',
                        'message', '批量运单无法建立逐行姓名—运单号对应关系，系统不按两个列表的位置猜测配对')
                    || CASE
                         WHEN jsonb_array_length(names) > 0 OR jsonb_array_length(tracking_nos) > 0
                             THEN jsonb_build_object(
                                 'model_output',
                                 '{}'::jsonb
                                 || CASE WHEN jsonb_array_length(names) > 0
                                      THEN jsonb_build_object('names', names)
                                      ELSE '{}'::jsonb END
                                 || CASE WHEN jsonb_array_length(tracking_nos) > 0
                                      THEN jsonb_build_object('tracking_nos', tracking_nos)
                                      ELSE '{}'::jsonb END)
                         ELSE '{}'::jsonb
                       END
                ELSE '{}'::jsonb
              END AS safe_detail
    FROM review_history
)
UPDATE app.review_cases rc
SET detail = sanitized.safe_detail,
    updated_at = CURRENT_TIMESTAMP
FROM sanitized
WHERE rc.id = sanitized.id
  AND rc.detail IS DISTINCT FROM sanitized.safe_detail;

COMMENT ON COLUMN app.async_tasks.last_error IS
    'INTERPRET_MESSAGE rows use stable public failure codes; V20 normalizes older free-form values.';
COMMENT ON COLUMN app.message_interpretations.error IS
    'Stable message interpretation failure code; provider and SDK exception text is never public data.';
-- END V20__sanitize_wecom_message_public_history.sql

-- BEGIN V21__add_carrier_prefix_mappings.sql
-- Ticket 09: runtime-maintained, versioned carrier-prefix authority.
