-- BEGIN V25__media_evidence_columns.sql
-- ---------------------------------------------------------------------------
-- 媒体证据链路：扩展 V8 已建立的 app.message_media
--
-- V8 已建 message_media（下载状态 / 受控文件引用 / 哈希 / 内容类型 / 大小 /
-- 解密信息 / 失败原因 / 幂等键 UNIQUE (channel_message_id, channel_media_id)），
