-- BEGIN V46__wecom_export_outbound_send.sql
-- Issue #84：第三方履约导出 → 企微群自动发送 + 可手动重发 + 周期回传提醒。
--
-- 深模块（docs/agents/wecom-outbound-send.md）：一张导出状态表 + 一张 delivery 证据表。
-- - 状态表：每第三方导出唯一一行，持久化 provider/chat 路由证据、SLA/提醒间隔快照、
--   initial sent_at（= 文件消息 aibot_send_msg 成功 ack 时刻）、tracking_due_at、
--   next_reminder_at / last_reminded_at / reminder_count，以及终态
--   PENDING / ACTIVE / COMPLETED / MANUALLY_STOPPED / FAILED / UNKNOWN / LEGACY。
-- - delivery 表：每次 initial/reminder 尝试的证据（PENDING→SENDING→SENT/FAILED/UNKNOWN），
--   UNIQUE (export_id, kind, sequence) 保证同一 initial 或同一 reminder sequence
--   不会重复入队/并发发送；不持久化 media_id（3 天临时引用）或文件内容，只存摘要。
-- - 迁移安全默认：历史第三方导出登记为 LEGACY 终态，绝不自动入队、绝不部署后补发。

-- ① 旧 tracking_due_at（generated_at 派生）对新第三方导出不再是公开权威：
--    发送 ack 前为 NULL（API/UI 不得展示假的「已到期时间」），历史/JD 行保持既有语义。
ALTER TABLE app.fulfillment_exports ALTER COLUMN tracking_due_at DROP NOT NULL;

-- ② 每第三方导出一行出站/提醒状态
CREATE TABLE app.fulfillment_export_wecom_states (
    export_id                BIGINT PRIMARY KEY
                             REFERENCES app.fulfillment_exports(id) ON DELETE RESTRICT,
    provider_id              BIGINT NOT NULL
                             REFERENCES app.fulfillment_providers(id) ON DELETE RESTRICT,
    status                   VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                             CHECK (status IN (
                                 'PENDING', 'ACTIVE', 'COMPLETED', 'MANUALLY_STOPPED',
                                 'FAILED', 'UNKNOWN', 'LEGACY')),
    chat_id                  VARCHAR(128),
    tracking_sla_minutes     INTEGER NOT NULL CHECK (tracking_sla_minutes > 0),
    reminder_interval_minutes INTEGER NOT NULL CHECK (reminder_interval_minutes > 0),
    initial_sent_at          TIMESTAMPTZ,
    tracking_due_at          TIMESTAMPTZ,
    next_reminder_at         TIMESTAMPTZ,
    last_reminded_at         TIMESTAMPTZ,
    reminder_count           INTEGER NOT NULL DEFAULT 0 CHECK (reminder_count >= 0),
    last_error               VARCHAR(512),
    stopped_by               VARCHAR(128),
    stopped_reason           TEXT,
    stopped_at               TIMESTAMPTZ,
    lock_version             BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at               TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at               TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (chat_id IS NULL OR btrim(chat_id) <> ''),
    -- ACTIVE 由 initial 成功 ack 进入：计时起点、due 与快照群必须齐备
    CHECK ((status <> 'ACTIVE') OR (
        initial_sent_at IS NOT NULL AND tracking_due_at IS NOT NULL AND chat_id IS NOT NULL)),
    -- 收齐后不再自动提醒
    CHECK ((status <> 'COMPLETED') OR next_reminder_at IS NULL),
    -- 人工停止必须留证据
    CHECK ((status <> 'MANUALLY_STOPPED') OR (stopped_by IS NOT NULL AND stopped_at IS NOT NULL)),
    -- 历史导出安全默认：从未发送
    CHECK ((status <> 'LEGACY') OR initial_sent_at IS NULL),
    -- next_reminder_at 只属于 ACTIVE（其余状态一律清空，暂停/停止/收齐即不再提醒）
    CHECK (next_reminder_at IS NULL OR status = 'ACTIVE'),
    CHECK (initial_sent_at IS NULL OR tracking_due_at IS NOT NULL)
);

CREATE INDEX idx_wecom_states_reminder_due
    ON app.fulfillment_export_wecom_states (status, next_reminder_at, export_id)
    WHERE status = 'ACTIVE';

-- ③ 每次 delivery 尝试的证据（唯一键 = 数据库级「同一 initial/同一 reminder 不重复入队」）
CREATE TABLE app.fulfillment_export_wecom_deliveries (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    export_id            BIGINT NOT NULL
                         REFERENCES app.fulfillment_export_wecom_states(export_id) ON DELETE RESTRICT,
    kind                 VARCHAR(16) NOT NULL CHECK (kind IN ('INITIAL', 'REMINDER')),
    sequence             INTEGER NOT NULL CHECK (sequence > 0),
    status               VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                         CHECK (status IN ('PENDING', 'SENDING', 'SENT', 'FAILED', 'UNKNOWN')),
    attempts             INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts         INTEGER NOT NULL DEFAULT 2 CHECK (max_attempts >= 1),
    stage                VARCHAR(32) NOT NULL DEFAULT 'SCHEDULED'
                         CHECK (stage IN ('SCHEDULED', 'RESOLVE_CHAT', 'UPLOAD', 'SEND', 'FINALIZED')),
    chat_id              VARCHAR(128),
    request_id           VARCHAR(128),
    ack_sent_at          TIMESTAMPTZ,
    media_id_sha256      CHAR(64),
    error_code           VARCHAR(64),
    error_message        VARCHAR(512),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (export_id, kind, sequence),
    CHECK (media_id_sha256 IS NULL OR media_id_sha256 ~ '^[0-9a-f]{64}$'),
    -- SENT 必须携带服务端 ack 接收时刻（计时起点证据），其余状态不得携带
    CHECK ((status = 'SENT') = (ack_sent_at IS NOT NULL))
);

-- ④ 历史第三方导出安全默认：LEGACY（不自动入队、不提醒、不补发）
INSERT INTO app.fulfillment_export_wecom_states
    (export_id, provider_id, status, tracking_sla_minutes, reminder_interval_minutes)
SELECT fe.id, fe.fulfillment_provider_id, 'LEGACY',
       fp.tracking_sla_minutes, fp.tracking_sla_minutes
FROM app.fulfillment_exports fe
JOIN app.fulfillment_providers fp ON fp.id = fe.fulfillment_provider_id
WHERE fe.export_kind = 'THIRD_PARTY'
ON CONFLICT (export_id) DO NOTHING;
-- END V46__wecom_export_outbound_send.sql

-- BEGIN V47__wecom_export_alert_scoping.sql
-- Issue #84（第二轮修复）：企微导出告警按 (shipment_id, detail.export_id) 隔离，不跨导出误关。
--
-- 背景：续发导出可与原导出共享 fulfillment/shipment。旧的全局 subject 唯一索引
-- （uq_operational_alert_active_subject，按 order/order_line/fulfillment/shipment 组合）
-- 会让两个导出对同一 shipment 的活动告警互相冲突（并发 ensure 时返回对方导出的告警，
-- 或新导出告警无法落库），且按 fulfillment 的 supersede 会误关另一个导出的活动告警。
--
-- 拆分：
--  - 非企微导出告警沿用原 (alert_type, subject) 唯一语义（行为不变）；
--  - 企微导出告警按 (alert_type, shipment_id, detail->>'export_id') 唯一——同一导出
--    同一 delivery 多次 ensure 只一条活动告警，绝不跨导出（续发共享 shipment 也互不影响）。
DROP INDEX app.uq_operational_alert_active_subject;

CREATE UNIQUE INDEX uq_operational_alert_active_subject
    ON app.operational_alerts(
        alert_type,
        (COALESCE(order_id, 0)),
        (COALESCE(order_line_id, 0)),
        (COALESCE(fulfillment_id, 0)),
        (COALESCE(shipment_id, 0)))
    WHERE status IN ('OPEN', 'ACKNOWLEDGED') AND alert_type <> 'FULFILLMENT_EXPORT_WECOM';

CREATE UNIQUE INDEX uq_operational_alert_active_wecom_export
    ON app.operational_alerts(
        alert_type,
        (COALESCE(shipment_id, 0)),
        (detail->>'export_id'))
    WHERE alert_type = 'FULFILLMENT_EXPORT_WECOM' AND status IN ('OPEN', 'ACKNOWLEDGED');
-- END V47__wecom_export_alert_scoping.sql

-- BEGIN V48__internal_operators.sql
-- Issue #89：内部运营人员登记（姓名、企微 userid、所属责任团队）。
--
-- 系统第一次有「人」的概念：可登记内部运营人员并绑定企微 userid，从而知道
-- 「这条复核该推给谁」；responsible_team 由此可解析到具体人员列表。
--
-- 边界（与 Issue 一致）：
--  - 只做「运营人员 ↔ 企微 userid ↔ 责任团队」映射与责任归属，不做登录/角色/权限；
--  - 不把 channel_identities 当内部员工表（渠道侧身份是客户与群的证据，不是员工档案）；
--  - 不做物理删除：停用（active=false）即可，解析 seam 只返回 active 人员。
--
-- 约束语义：
--  - display_name / responsible_team 非空；responsible_team 由写入侧统一
--    trim + 大写归一（ORDER_OPS / CUSTOMER_OPS / SKU_OPS 等既有取值），DB 侧兜底
--    拒绝纯空白与未大写团队；
--  - wecom_userid 可空（未绑定）：非空时全局唯一——同一企微 userid 永远只映射一个
--    人员（停用后重新启用同一行，或先清除旧绑定再换绑）；
--  - 企微 userid 按官方规则校验：1..64 字节，首字符必须为数字或字母，可含 _ - @ .
--    四种字符；真实企微实测确认前以本保守规则为准（见 docs/agents/operator-wecom-userid.md）。
CREATE TABLE app.internal_operators (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    display_name     VARCHAR(64) NOT NULL CHECK (btrim(display_name) <> ''),
    responsible_team VARCHAR(32) NOT NULL
                     CHECK (btrim(responsible_team) <> ''
                            AND responsible_team = upper(responsible_team)),
    wecom_userid     VARCHAR(64),
    active           BOOLEAN NOT NULL DEFAULT TRUE,
    lock_version     BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (wecom_userid IS NULL
           OR wecom_userid ~ '^[A-Za-z0-9][A-Za-z0-9_@.\-]{0,63}$')
);

-- 同一企微 userid 全局唯一；未绑定（NULL）行不互相冲突。
CREATE UNIQUE INDEX uq_internal_operators_wecom_userid
    ON app.internal_operators (wecom_userid) WHERE wecom_userid IS NOT NULL;

-- 解析 seam 按责任团队 + 启用状态查询的支撑索引。
CREATE INDEX idx_internal_operators_team_active
    ON app.internal_operators (responsible_team, active);
-- END V48__internal_operators.sql

-- BEGIN V49__wecom_export_delivery_generation_fencing.sql
-- Issue #84（第三轮修复）：delivery 代际栅栏（generation fencing）。
--
-- 背景（详见 docs/agents/wecom-outbound-send.md §10.6）：
--  1) INITIAL beginAttempt 与 REMINDER prepareReminder 必须在「活跃租约 owner 复查 + 续租」与
--     「delivery PENDING→SENDING + recipient 持久化」同一短事务内线性化，否则旧 Worker 丢失
--     租约后仍可把 delivery 拉到 SENDING，使新 owner 误判 UNKNOWN；
--  2) 旧 REMINDER 的迟到 SUCCESS/FAILED/UNKNOWN 可能覆盖更晚成功的新 INITIAL 时间线——提醒必须
--     绑定到「创建/准备时的 INITIAL 代际」（复用已有的 INITIAL delivery sequence 作为代际），
--     代际变化后旧提醒结果只落 SUPERSEDED 证据，绝不改新时间线/reminder_count/next_reminder_at/告警；
--  3) 旧 INITIAL phase-2 成功收口可能关闭更新代际 resend 失败的红告警——告警关闭必须按成功
--     delivery 的 INITIAL 代际收窄（只关 <= 该代际的告警）。
--
-- 迁移协调：组合基线已经包含 #89（V48）；本迁移以连续 V49 只追加一列
-- initial_generation 并扩展 status 允许 SUPERSEDED，只改本功能自有的 deliveries 表。
-- 尚未合入的 #90 后续必须改用下一空闲版本 V50，见 docs/agents/wecom-outbound-send.md §10.6。

ALTER TABLE app.fulfillment_export_wecom_deliveries
    ADD COLUMN initial_generation INTEGER;

-- INITIAL 行：代际 = 自身 sequence（INITIAL 自己就是代际锚点）。
UPDATE app.fulfillment_export_wecom_deliveries
SET initial_generation = sequence
WHERE kind = 'INITIAL';

-- REMINDER 行：代际 = 插入该提醒前已经存在的最新 INITIAL sequence。同一 export 的 identity id
-- 是提交到 delivery 表的线性顺序；created_at 使用事务开始时刻，长事务下会反序，不能作为依据。
UPDATE app.fulfillment_export_wecom_deliveries d
SET initial_generation = (
    SELECT COALESCE(MAX(i.sequence), 1)
    FROM app.fulfillment_export_wecom_deliveries i
    WHERE i.export_id = d.export_id
      AND i.kind = 'INITIAL'
      AND i.id < d.id)
WHERE d.kind = 'REMINDER';

ALTER TABLE app.fulfillment_export_wecom_deliveries
    ALTER COLUMN initial_generation SET NOT NULL;

ALTER TABLE app.fulfillment_export_wecom_deliveries
    ADD CONSTRAINT fulfillment_export_wecom_deliveries_initial_generation_check
    CHECK (initial_generation > 0);

-- status 允许 SUPERSEDED：旧提醒被更新 INITIAL 代际取代的诚实终态（不触发告警、不改时间线）。
ALTER TABLE app.fulfillment_export_wecom_deliveries
    DROP CONSTRAINT fulfillment_export_wecom_deliveries_status_check;

ALTER TABLE app.fulfillment_export_wecom_deliveries
    ADD CONSTRAINT fulfillment_export_wecom_deliveries_status_check
    CHECK (status IN ('PENDING', 'SENDING', 'SENT', 'FAILED', 'UNKNOWN', 'SUPERSEDED'));

-- V46 的匿名 CHECK 要求只有 SENT 可带 ack_sent_at。迟到 reminder 的外部 SUCCESS 会落
-- SUPERSEDED（不推进新时间线），但仍必须保留真实 ACK 证据，因此替换为显式命名约束：
-- SENT 必须有 ACK；普通非成功状态不得有 ACK；SUPERSEDED 可有或无 ACK（对应迟到成功/失败）。
DO $$
DECLARE
    ack_constraint TEXT;
BEGIN
    SELECT conname INTO ack_constraint
    FROM pg_constraint
    WHERE conrelid = 'app.fulfillment_export_wecom_deliveries'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%ack_sent_at%'
      AND pg_get_constraintdef(oid) LIKE '%SENT%';
    IF ack_constraint IS NULL THEN
        RAISE EXCEPTION 'delivery ack/status check constraint not found';
    END IF;
    EXECUTE format(
        'ALTER TABLE app.fulfillment_export_wecom_deliveries DROP CONSTRAINT %I',
        ack_constraint);
END
$$;

ALTER TABLE app.fulfillment_export_wecom_deliveries
    ADD CONSTRAINT fulfillment_export_wecom_deliveries_ack_status_check
    CHECK (
        (status = 'SENT' AND ack_sent_at IS NOT NULL)
        OR status = 'SUPERSEDED'
        OR (status IN ('PENDING', 'SENDING', 'FAILED', 'UNKNOWN') AND ack_sent_at IS NULL));
-- END V49__wecom_export_delivery_generation_fencing.sql

-- BEGIN V51__wecom_business_notification_outbox.sql
-- Issue #90: durable five-minute WeCom digests for review cases and key business events.
-- Capture happens in the same database transaction as the source fact. Delivery is fenced in
-- separate durable batches so a process crash after submission becomes UNKNOWN, never a blind resend.

CREATE TABLE app.wecom_notification_batches (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    responsible_team    VARCHAR(128) NOT NULL CHECK (btrim(responsible_team) <> ''),
    window_start        TIMESTAMPTZ NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                        CHECK (status IN ('PENDING', 'RUNNING', 'SENT', 'PARTIAL',
                                          'BLOCKED', 'UNKNOWN', 'FAILED')),
    next_attempt_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_until         TIMESTAMPTZ,
    lease_owner         VARCHAR(128),
    last_reason_code    VARCHAR(128),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        (status = 'RUNNING' AND lease_until IS NOT NULL AND lease_owner IS NOT NULL)
        OR (status <> 'RUNNING' AND lease_until IS NULL AND lease_owner IS NULL)
    )
);

CREATE INDEX idx_wecom_notification_batches_due
    ON app.wecom_notification_batches (status, next_attempt_at, id)
    WHERE status IN ('PENDING', 'RUNNING');

CREATE TABLE app.wecom_notification_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_type         VARCHAR(32) NOT NULL
                        CHECK (source_type IN ('REVIEW_CASE', 'ORDER_EVENT')),
    source_id           BIGINT NOT NULL CHECK (source_id > 0),
    notification_kind   VARCHAR(32) NOT NULL
                        CHECK (notification_kind IN ('REVIEW_CASE', 'ORDER_CREATED', 'SHIPMENT_COMPLETED')),
    responsible_team    VARCHAR(128) NOT NULL CHECK (btrim(responsible_team) <> ''),
    summary             JSONB NOT NULL CHECK (jsonb_typeof(summary) = 'object'),
    window_start        TIMESTAMPTZ NOT NULL,
    available_at        TIMESTAMPTZ NOT NULL,
    batch_id            BIGINT REFERENCES app.wecom_notification_batches(id) ON DELETE RESTRICT,
    status              VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                        CHECK (status IN ('PENDING', 'BATCHED', 'SENT', 'PARTIAL',
                                          'BLOCKED', 'UNKNOWN', 'FAILED')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (source_type, source_id, notification_kind),
    CHECK (
        (status = 'PENDING' AND batch_id IS NULL)
        OR (status <> 'PENDING' AND batch_id IS NOT NULL)
    )
);

CREATE INDEX idx_wecom_notification_items_due
    ON app.wecom_notification_items (available_at, responsible_team, window_start, id)
    WHERE status = 'PENDING' AND batch_id IS NULL;

CREATE INDEX idx_wecom_notification_items_batch
    ON app.wecom_notification_items (batch_id, id)
    WHERE batch_id IS NOT NULL;

CREATE TABLE app.wecom_notification_deliveries (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id                BIGINT NOT NULL REFERENCES app.wecom_notification_batches(id) ON DELETE RESTRICT,
    recipient_key           VARCHAR(255) NOT NULL CHECK (btrim(recipient_key) <> ''),
    recipient_display_name  VARCHAR(64),
    recipient_userid        VARCHAR(64),
    status                  VARCHAR(16) NOT NULL
                            CHECK (status IN ('SENDING', 'SENT', 'RETRY_PENDING',
                                              'BLOCKED', 'UNKNOWN', 'FAILED')),
    attempt_count           INT NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    content_sha256          CHAR(64),
    request_id              VARCHAR(128),
    reason_code             VARCHAR(128),
    reason_message          VARCHAR(255),
    acknowledged_at         TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (batch_id, recipient_key),
    CHECK (content_sha256 IS NULL OR content_sha256 ~ '^[0-9a-f]{64}$'),
    CHECK (
        (status = 'SENT' AND request_id IS NOT NULL AND acknowledged_at IS NOT NULL)
        OR status <> 'SENT'
    )
);

CREATE INDEX idx_wecom_notification_deliveries_source
    ON app.wecom_notification_deliveries (batch_id, status, id);

-- Durable operations projection for every blocked, failed or unknown source x recipient result.
-- It is intentionally independent from operational_alerts: some notifications point only to an
-- import/message/draft subject, while operational_alerts requires an order-side foreign key.
CREATE TABLE app.wecom_notification_alerts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alert_key           VARCHAR(128) NOT NULL UNIQUE CHECK (btrim(alert_key) <> ''),
    delivery_id         BIGINT NOT NULL REFERENCES app.wecom_notification_deliveries(id) ON DELETE RESTRICT,
    item_id             BIGINT NOT NULL REFERENCES app.wecom_notification_items(id) ON DELETE RESTRICT,
    batch_id            BIGINT NOT NULL REFERENCES app.wecom_notification_batches(id) ON DELETE RESTRICT,
    delivery_status     VARCHAR(16) NOT NULL CHECK (delivery_status IN ('BLOCKED', 'UNKNOWN', 'FAILED')),
    severity            VARCHAR(16) NOT NULL CHECK (severity IN ('YELLOW', 'RED')),
    reason_code         VARCHAR(128),
    reason_message      VARCHAR(255),
    order_id            BIGINT REFERENCES app.orders(id) ON DELETE RESTRICT,
    order_line_id       BIGINT REFERENCES app.order_lines(id) ON DELETE RESTRICT,
    fulfillment_id      BIGINT REFERENCES app.fulfillments(id) ON DELETE RESTRICT,
    shipment_id         BIGINT REFERENCES app.shipments(id) ON DELETE RESTRICT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (delivery_id, item_id)
);

CREATE INDEX idx_wecom_notification_alerts_queue
    ON app.wecom_notification_alerts (severity, created_at DESC, id DESC);
CREATE INDEX idx_wecom_notification_alerts_batch
    ON app.wecom_notification_alerts (batch_id, id);
CREATE INDEX idx_wecom_notification_alerts_order
    ON app.wecom_notification_alerts (order_id) WHERE order_id IS NOT NULL;

CREATE FUNCTION app.wecom_notification_window_start(value TIMESTAMPTZ)
RETURNS TIMESTAMPTZ
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT (
        date_trunc('hour', value AT TIME ZONE 'UTC')
        + ((extract(minute FROM value AT TIME ZONE 'UTC')::INT / 5) * INTERVAL '5 minutes')
    ) AT TIME ZONE 'UTC'
$$;

CREATE FUNCTION app.capture_review_case_wecom_notification()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_scope VARCHAR(16);
    v_order_no VARCHAR(64);
    v_subject_order_id BIGINT;
    v_window TIMESTAMPTZ;
BEGIN
    IF NEW.status <> 'OPEN' THEN
        RETURN NEW;
    END IF;

    v_subject_order_id := NEW.order_id;
    IF v_subject_order_id IS NULL AND NEW.order_line_id IS NOT NULL THEN
        SELECT order_id INTO v_subject_order_id
        FROM app.order_lines WHERE id = NEW.order_line_id;
    END IF;
    IF v_subject_order_id IS NULL AND NEW.fulfillment_id IS NOT NULL THEN
        SELECT ol.order_id INTO v_subject_order_id
        FROM app.fulfillments f
        JOIN app.order_lines ol ON ol.id = f.order_line_id
        WHERE f.id = NEW.fulfillment_id;
    END IF;
    IF v_subject_order_id IS NULL AND NEW.shipment_id IS NOT NULL THEN
        SELECT order_id INTO v_subject_order_id
        FROM app.shipments WHERE id = NEW.shipment_id;
    END IF;
    IF v_subject_order_id IS NULL AND NEW.raw_import_row_id IS NOT NULL THEN
        SELECT COALESCE(r.order_id, ol.order_id) INTO v_subject_order_id
        FROM app.raw_import_rows r
        LEFT JOIN app.order_lines ol ON ol.id = r.order_line_id
        WHERE r.id = NEW.raw_import_row_id;
    END IF;

    IF v_subject_order_id IS NOT NULL THEN
        SELECT data_scope, order_no INTO v_scope, v_order_no
        FROM app.orders WHERE id = v_subject_order_id;
        IF v_scope IS DISTINCT FROM 'BUSINESS' THEN
            RETURN NEW;
        END IF;
    END IF;

    v_window := app.wecom_notification_window_start(NEW.created_at);
    INSERT INTO app.wecom_notification_items (
        source_type, source_id, notification_kind, responsible_team,
        summary, window_start, available_at
    ) VALUES (
        'REVIEW_CASE', NEW.id, 'REVIEW_CASE', NEW.responsible_team,
        jsonb_strip_nulls(jsonb_build_object(
            'case_no', NEW.case_no,
            'reason_code', NEW.reason_code,
            'order_no', v_order_no,
            'order_id', v_subject_order_id,
            'order_line_id', NEW.order_line_id,
            'fulfillment_id', NEW.fulfillment_id,
            'shipment_id', NEW.shipment_id,
            'import_batch_id', NEW.import_batch_id,
            'raw_import_row_id', NEW.raw_import_row_id,
            'message_submission_id', NEW.message_submission_id,
            'order_draft_id', NEW.order_draft_id,
            'provider_tracking_draft_id', NEW.provider_tracking_draft_id
        )),
        v_window,
        v_window + INTERVAL '5 minutes'
    ) ON CONFLICT (source_type, source_id, notification_kind) DO NOTHING;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_review_case_wecom_notification
AFTER INSERT ON app.review_cases
FOR EACH ROW EXECUTE FUNCTION app.capture_review_case_wecom_notification();

CREATE FUNCTION app.capture_order_event_wecom_notification()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_kind VARCHAR(32);
    v_team VARCHAR(128);
    v_order_no VARCHAR(64);
    v_source_channel VARCHAR(32);
    v_window TIMESTAMPTZ;
BEGIN
    IF NEW.data_scope <> 'BUSINESS'
       OR NEW.event_type_code NOT IN ('ORDER_RECEIVED', 'TRACKING_RECEIVED') THEN
        RETURN NEW;
    END IF;

    IF NEW.event_type_code = 'ORDER_RECEIVED' THEN
        v_kind := 'ORDER_CREATED';
        v_team := 'ORDER_OPS';
    ELSE
        v_kind := 'SHIPMENT_COMPLETED';
        v_team := 'FULFILLMENT_OPS';
    END IF;

    SELECT order_no, source_channel INTO v_order_no, v_source_channel
    FROM app.orders WHERE id = NEW.order_id;
    v_window := app.wecom_notification_window_start(NEW.created_at);
    INSERT INTO app.wecom_notification_items (
        source_type, source_id, notification_kind, responsible_team,
        summary, window_start, available_at
    ) VALUES (
        'ORDER_EVENT', NEW.id, v_kind, v_team,
        jsonb_strip_nulls(jsonb_build_object(
            'event_type_code', NEW.event_type_code,
            'order_no', v_order_no,
            'order_id', NEW.order_id,
            'source_channel', v_source_channel,
            'shipment_id', NEW.shipment_id
        )),
        v_window,
        v_window + INTERVAL '5 minutes'
    ) ON CONFLICT (source_type, source_id, notification_kind) DO NOTHING;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_order_event_wecom_notification
AFTER INSERT ON app.order_events
FOR EACH ROW EXECUTE FUNCTION app.capture_order_event_wecom_notification();
-- END V51__wecom_business_notification_outbox.sql

-- BEGIN V52__wecom_order_draft_cards.sql
-- Issues #87/#88: persisted order-draft cards, traceable click outcomes and 5s update state.

ALTER TABLE app.order_drafts
    ADD COLUMN settlement_time TIMESTAMPTZ;

-- Confirmed legacy drafts did not persist this fact on the draft, but their canonical order does.
UPDATE app.order_drafts d
SET settlement_time = o.settlement_time
FROM app.review_cases rc
JOIN app.orders o ON o.id = CASE
    WHEN rc.resolution->>'order_id' ~ '^[1-9][0-9]*$'
    THEN (rc.resolution->>'order_id')::BIGINT
END
WHERE rc.order_draft_id = d.id
  AND rc.status = 'RESOLVED'
  AND rc.resolution->>'resolution_type' = 'ORDER_DRAFT_CONFIRMED'
  AND d.status = 'CONFIRMED'
  AND d.settlement_time IS NULL;

-- Only open legacy drafts need a new missing-field gate. Closed historical drafts must not be
-- rewritten to look incomplete.
UPDATE app.order_drafts
SET missing_fields = missing_fields || '["settlement_time"]'::jsonb
WHERE status = 'OPEN'
  AND settlement_time IS NULL
  AND NOT (missing_fields ? 'settlement_time');

ALTER TABLE app.wecom_events
    ADD COLUMN event_key VARCHAR(64),
    ADD COLUMN task_id VARCHAR(128),
    ADD COLUMN order_draft_id BIGINT REFERENCES app.order_drafts(id) ON DELETE RESTRICT,
    ADD COLUMN processing_status VARCHAR(32),
    ADD COLUMN business_code VARCHAR(128),
    ADD COLUMN processed_by VARCHAR(255),
    ADD COLUMN processing_started_at TIMESTAMPTZ,
    ADD COLUMN processed_at TIMESTAMPTZ,
    ADD COLUMN processing_claim_token UUID,
    ADD COLUMN processing_attempt INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN update_status VARCHAR(32),
    ADD COLUMN update_latency_ms INTEGER,
    ADD COLUMN update_error_code VARCHAR(128),
    ADD COLUMN fallback_status VARCHAR(32),
    ADD COLUMN fallback_error_code VARCHAR(128);

ALTER TABLE app.wecom_events
    ADD CONSTRAINT wecom_events_processing_status_check CHECK (
        processing_status IS NULL OR processing_status IN (
            'RECEIVED', 'PROCESSING', 'CONFIRMED', 'MISSING_INFORMATION', 'ALREADY_CONFIRMED',
            'REJECTED', 'FAILED'
        )
    ),
    ADD CONSTRAINT wecom_events_update_status_check CHECK (
        update_status IS NULL OR update_status IN (
            'NOT_ATTEMPTED', 'SENT', 'TIMED_OUT', 'FAILED'
        )
    ),
    ADD CONSTRAINT wecom_events_fallback_status_check CHECK (
        fallback_status IS NULL OR fallback_status IN ('NOT_ATTEMPTED', 'SENT', 'FAILED')
    ),
    ADD CONSTRAINT wecom_events_update_latency_check CHECK (
        update_latency_ms IS NULL OR update_latency_ms >= 0
    ),
    ADD CONSTRAINT wecom_events_processing_claim_check CHECK (
        processing_status IS NULL
        OR (processing_status = 'RECEIVED'
            AND processing_claim_token IS NULL AND processing_attempt = 0)
        OR (processing_status <> 'RECEIVED'
            AND processing_claim_token IS NOT NULL AND processing_attempt >= 1)
    );

CREATE OR REPLACE FUNCTION app.guard_wecom_card_event_first_facts()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF OLD.event_type = 'template_card_event' AND (
        NEW.event_type IS DISTINCT FROM OLD.event_type
        OR NEW.msgid IS DISTINCT FROM OLD.msgid
        OR NEW.aibot_id IS DISTINCT FROM OLD.aibot_id
        OR NEW.chat_id IS DISTINCT FROM OLD.chat_id
        OR NEW.chat_type IS DISTINCT FROM OLD.chat_type
        OR NEW.from_user_id IS DISTINCT FROM OLD.from_user_id
        OR NEW.create_time IS DISTINCT FROM OLD.create_time
        OR NEW.raw_payload IS DISTINCT FROM OLD.raw_payload
        OR NEW.event_key IS DISTINCT FROM OLD.event_key
        OR NEW.task_id IS DISTINCT FROM OLD.task_id
        OR NEW.order_draft_id IS DISTINCT FROM OLD.order_draft_id
    ) THEN
        RAISE EXCEPTION 'template-card first facts are immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_wecom_card_event_first_facts
    BEFORE UPDATE ON app.wecom_events
    FOR EACH ROW
    EXECUTE FUNCTION app.guard_wecom_card_event_first_facts();

CREATE INDEX idx_wecom_events_task
    ON app.wecom_events (task_id, received_at DESC)
    WHERE task_id IS NOT NULL;

CREATE TABLE app.wecom_order_draft_cards (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_draft_id      BIGINT NOT NULL UNIQUE REFERENCES app.order_drafts(id) ON DELETE RESTRICT,
    draft_revision      BIGINT NOT NULL CHECK (draft_revision >= 0),
    task_id             VARCHAR(128) NOT NULL UNIQUE CHECK (btrim(task_id) <> ''),
    route_type          VARCHAR(16) NOT NULL CHECK (route_type IN ('SINGLE', 'GROUP')),
    chat_id             VARCHAR(255) NOT NULL CHECK (btrim(chat_id) <> ''),
    status              VARCHAR(16) NOT NULL DEFAULT 'PENDING'
                        CHECK (status IN ('PENDING', 'SENDING', 'SENT', 'UNKNOWN', 'FAILED', 'SUPERSEDED')),
    attempt_count       INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    request_id          VARCHAR(128),
    last_error          VARCHAR(128),
    acknowledged_at     TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        (status = 'SENT' AND request_id IS NOT NULL AND acknowledged_at IS NOT NULL)
        OR status <> 'SENT'
    )
);

CREATE INDEX idx_wecom_order_draft_cards_status
    ON app.wecom_order_draft_cards (status, id);
-- END V52__wecom_order_draft_cards.sql

-- BEGIN V53__shipment_source_sync.sql
-- Issue #113: Shipment-scoped source-platform sync projection, durable intent and
-- bidirectional exclusion with the existing SourceReturnExport fallback path.

ALTER TABLE app.shipment_syncs
    ADD COLUMN intent_key VARCHAR(255),
    ADD COLUMN platform_intent_key VARCHAR(255),
    ADD COLUMN check_hash CHAR(64),
    ADD COLUMN artifact_hash CHAR(64),
    ADD COLUMN source_line_ref VARCHAR(255),
    ADD COLUMN carrier_code VARCHAR(64),
    ADD COLUMN tracking_number VARCHAR(128),
    ADD COLUMN intent_started_at TIMESTAMPTZ,
    ADD COLUMN effect_started_at TIMESTAMPTZ,
    ADD COLUMN lock_version BIGINT NOT NULL DEFAULT 0;

ALTER TABLE app.shipment_syncs
    DROP CONSTRAINT shipment_syncs_sync_status_check,
    ADD CONSTRAINT shipment_syncs_sync_status_check CHECK (
        sync_status IN (
            'PENDING',
            'SYNCING',
            'SYNCED',
            'SYNC_FAILED',
            'RECONCILIATION_REQUIRED'
        )
    ),
    ADD CONSTRAINT shipment_syncs_intent_key_not_blank CHECK (
        intent_key IS NULL OR btrim(intent_key) <> ''
    ),
    ADD CONSTRAINT shipment_syncs_platform_intent_key_not_blank CHECK (
        platform_intent_key IS NULL OR btrim(platform_intent_key) <> ''
    ),
    ADD CONSTRAINT shipment_syncs_check_hash_format CHECK (
        check_hash IS NULL OR check_hash ~ '^[0-9a-f]{64}$'
    ),
    ADD CONSTRAINT shipment_syncs_artifact_hash_format CHECK (
        artifact_hash IS NULL OR artifact_hash ~ '^[0-9a-f]{64}$'
    ),
    ADD CONSTRAINT shipment_syncs_source_line_ref_not_blank CHECK (
        source_line_ref IS NULL OR btrim(source_line_ref) <> ''
    ),
    ADD CONSTRAINT shipment_syncs_carrier_code_not_blank CHECK (
        carrier_code IS NULL OR btrim(carrier_code) <> ''
    ),
    ADD CONSTRAINT shipment_syncs_tracking_number_not_blank CHECK (
        tracking_number IS NULL OR btrim(tracking_number) <> ''
    ),
    ADD CONSTRAINT shipment_syncs_lock_version_nonnegative CHECK (lock_version >= 0),
    ADD CONSTRAINT shipment_syncs_effect_order_check CHECK (
        effect_started_at IS NULL
        OR (intent_started_at IS NOT NULL AND effect_started_at >= intent_started_at)
    ),
    ADD CONSTRAINT shipment_syncs_syncing_intent_check CHECK (
        sync_status <> 'SYNCING'
        OR (
            intent_key IS NOT NULL
            AND check_hash IS NOT NULL
            AND artifact_hash IS NOT NULL
            AND source_line_ref IS NOT NULL
            AND carrier_code IS NOT NULL
            AND tracking_number IS NOT NULL
            AND intent_started_at IS NOT NULL
            AND attempt_count > 0
            AND (source_channel <> 'JUFUBAO' OR platform_intent_key IS NOT NULL)
        )
    ),
    ADD CONSTRAINT shipment_syncs_reconciliation_effect_check CHECK (
        sync_status <> 'RECONCILIATION_REQUIRED'
        OR (
            intent_key IS NOT NULL
            AND check_hash IS NOT NULL
            AND artifact_hash IS NOT NULL
            AND source_line_ref IS NOT NULL
            AND carrier_code IS NOT NULL
            AND tracking_number IS NOT NULL
            AND intent_started_at IS NOT NULL
            AND effect_started_at IS NOT NULL
            AND attempt_count > 0
            AND (source_channel <> 'JUFUBAO' OR platform_intent_key IS NOT NULL)
        )
    ),
    ADD CONSTRAINT shipment_syncs_pending_fresh_check CHECK (
        sync_status <> 'PENDING'
        OR (
            intent_key IS NULL
            AND platform_intent_key IS NULL
            AND check_hash IS NULL
            AND artifact_hash IS NULL
            AND source_line_ref IS NULL
            AND carrier_code IS NULL
            AND tracking_number IS NULL
            AND intent_started_at IS NULL
            AND effect_started_at IS NULL
        )
    );

CREATE UNIQUE INDEX uq_shipment_syncs_intent
    ON app.shipment_syncs(source_channel, intent_key)
    WHERE intent_key IS NOT NULL;

CREATE UNIQUE INDEX uq_shipment_syncs_platform_intent
    ON app.shipment_syncs(source_channel, platform_intent_key)
    WHERE platform_intent_key IS NOT NULL;

-- V1 made generated source-return facts append-only. V34 later added a mutable push projection,
-- but the old trigger still rejected every UPDATE. Replace it with a narrow lifecycle guard:
-- generation facts stay immutable; only one legal push-status transition may update push fields.
CREATE FUNCTION app.guard_source_return_export_push_update() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'source return exports are append-only';
    END IF;

    IF ROW(
        NEW.id,
        NEW.import_batch_id,
        NEW.version_no,
        NEW.is_final,
        NEW.template_version,
        NEW.tracking_cutoff_at,
        NEW.file_ref,
        NEW.file_sha256,
        NEW.generated_by,
        NEW.generated_at,
        NEW.generated_from_tracking_batch_id
    ) IS DISTINCT FROM ROW(
        OLD.id,
        OLD.import_batch_id,
        OLD.version_no,
        OLD.is_final,
        OLD.template_version,
        OLD.tracking_cutoff_at,
        OLD.file_ref,
        OLD.file_sha256,
        OLD.generated_by,
        OLD.generated_at,
        OLD.generated_from_tracking_batch_id
    ) THEN
        RAISE EXCEPTION 'source return export generation facts are immutable';
    END IF;

    IF NEW.push_status IS NOT DISTINCT FROM OLD.push_status THEN
        IF ROW(
            NEW.push_started_at,
            NEW.pushed_at,
            NEW.pushed_by,
            NEW.push_platform_ref,
            NEW.push_error
        ) IS DISTINCT FROM ROW(
            OLD.push_started_at,
            OLD.pushed_at,
            OLD.pushed_by,
            OLD.push_platform_ref,
            OLD.push_error
        ) THEN
            RAISE EXCEPTION 'source return push fields require a status transition';
        END IF;
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.push_status IN ('NOT_PUSHED', 'FAILED') AND NEW.push_status = 'PUSHING')
        OR (OLD.push_status = 'PUSHING' AND NEW.push_status IN ('SUCCESS', 'FAILED'))
    ) THEN
        RAISE EXCEPTION 'invalid source return push transition: % -> %',
            OLD.push_status, NEW.push_status;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER trg_source_return_export_append_only ON app.source_return_exports;

CREATE TRIGGER trg_source_return_export_append_only
BEFORE UPDATE OR DELETE ON app.source_return_exports
FOR EACH ROW EXECUTE FUNCTION app.guard_source_return_export_push_update();

-- Online claim side of the mutex. Lock the Shipment row first so a concurrent parent-export
-- transition must wait, then reject both an in-flight and an already successful file fallback.
CREATE FUNCTION app.guard_shipment_source_sync_mutex() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.sync_status <> 'SYNCING' THEN
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM app.shipments
    WHERE id = NEW.shipment_id
    FOR UPDATE;

    IF EXISTS (
        SELECT 1
        FROM app.source_return_export_items item
        JOIN app.source_return_exports export
          ON export.id = item.source_return_export_id
        JOIN app.v_import_batch_effective_source source
          ON source.import_batch_id = export.import_batch_id
        WHERE item.shipment_id = NEW.shipment_id
          AND source.effective_source_channel = NEW.source_channel
          AND export.push_status IN ('PUSHING', 'SUCCESS')
    ) THEN
        RAISE EXCEPTION 'shipment source sync conflicts with active source return fallback';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_shipment_source_sync_mutex
BEFORE INSERT OR UPDATE OF sync_status, shipment_id, source_channel ON app.shipment_syncs
FOR EACH ROW EXECUTE FUNCTION app.guard_shipment_source_sync_mutex();

-- Serialize invalidation with a concurrent parent-export PUSHING claim on the same immutable row.
-- Whichever transaction gets the export row lock first wins; the other then observes the terminal fact.
CREATE OR REPLACE FUNCTION app.validate_source_return_invalidation() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    export_batch_id BIGINT;
    correction_batch_id BIGINT;
    export_push_status VARCHAR(16);
BEGIN
    SELECT import_batch_id, push_status INTO STRICT export_batch_id, export_push_status
    FROM app.source_return_exports
    WHERE id=NEW.source_return_export_id
    FOR UPDATE;

    SELECT import_batch_id INTO STRICT correction_batch_id
    FROM app.source_attribution_corrections WHERE id=NEW.source_attribution_correction_id;

    IF export_batch_id <> correction_batch_id THEN
        RAISE EXCEPTION 'source return invalidation must use a correction from the same import batch';
    END IF;
    IF export_push_status IN ('PUSHING', 'SUCCESS') THEN
        RAISE EXCEPTION 'a pushing or pushed source return export cannot be invalidated';
    END IF;
    RETURN NEW;
END;
$$;

-- File-fallback side of the mutex. Resolve every Shipment from immutable export items, acquire
-- Shipment row locks in stable id order, then check the shared shipment_syncs projection.
CREATE FUNCTION app.guard_source_return_fallback_mutex() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    source_channel_value VARCHAR(32);
    shipment_id_value BIGINT;
BEGIN
    IF NEW.push_status <> 'PUSHING'
       OR OLD.push_status IS NOT DISTINCT FROM 'PUSHING' THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM app.source_return_export_invalidations invalidation
        WHERE invalidation.source_return_export_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'invalidated source return export cannot be pushed';
    END IF;

    SELECT effective_source_channel
    INTO STRICT source_channel_value
    FROM app.v_import_batch_effective_source
    WHERE import_batch_id = NEW.import_batch_id;

    FOR shipment_id_value IN
        SELECT DISTINCT item.shipment_id
        FROM app.source_return_export_items item
        WHERE item.source_return_export_id = NEW.id
          AND item.shipment_id IS NOT NULL
        ORDER BY item.shipment_id
    LOOP
        PERFORM 1
        FROM app.shipments
        WHERE id = shipment_id_value
        FOR UPDATE;
    END LOOP;

    IF EXISTS (
        SELECT 1
        FROM app.source_return_export_items item
        JOIN app.shipment_syncs sync
          ON sync.shipment_id = item.shipment_id
         AND sync.source_channel = source_channel_value
        WHERE item.source_return_export_id = NEW.id
          AND sync.sync_status IN ('SYNCING', 'SYNCED', 'RECONCILIATION_REQUIRED')
    ) THEN
        RAISE EXCEPTION 'source return fallback conflicts with active shipment source sync';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_source_return_export_push_mutex
BEFORE UPDATE OF push_status ON app.source_return_exports
FOR EACH ROW EXECUTE FUNCTION app.guard_source_return_fallback_mutex();

-- Advisory-only Agent definition. It has one read-only tool, no write capability and no blanket
-- PII guard exemption; deterministic application checks remain authoritative.
INSERT INTO app.agent_definitions (
    agent_slug,
    name,
    description,
    system_prompt,
    prompt_version,
    model_ref,
    input_format,
    enabled,
    version,
    status,
    activated_by,
    activated_at,
    allow_write,
    guard_exemptions,
    output_schema,
    tool_whitelist
) VALUES (
    'source-sync-reviewer',
    '来源回传复核 Agent',
    '只读复核单个 Shipment 的来源回传确定性检查结果，仅提供人工决策建议。',
    $prompt$你是来源回传复核 Agent。你是只读、建议型复核者，只能调用 check_shipment_source_sync 查看确定性检查结果。

规则：
1. 只陈述工具返回的收货、数量、承运商、运单与平台状态差异，不猜测或补造事实；
2. 确定性 blocker 永远优先，你的建议不得覆盖 blocker；
3. 不得执行回传，不得对账，不得调用任何写工具，也不得把建议表述为人工授权；
4. 信息不足或守卫拒绝时明确转人工，不尝试规避守卫。
$prompt$,
    'source-sync-reviewer-v1',
    'app.agent',
    'STRUCTURED_JSON',
    true,
    1,
    'active',
    'system:v53-seed',
    CURRENT_TIMESTAMP,
    false,
    '[]'::jsonb,
    NULL,
    '["check_shipment_source_sync"]'::jsonb
);
